// Largeur du panneau desktop (doit correspondre à #panel dans le CSS) et
// marge autour du canvas à l'intérieur de #stage.
const PANEL_W = 280;
const STAGE_MARGIN = 12;

// Vrai en dessous de 700px sur un écran tactile (voir le @media assorti dans
// injectStyles) : #app passe en colonne, le panneau se met sous le canvas au
// lieu d'à côté. matchMedia() n'a besoin d'aucune feuille de style pour
// répondre — contrairement à getBoundingClientRect() (voir plus bas), il ne
// force donc jamais un calcul de mise en page prématuré.
function isMobileLayout() {
  return window.matchMedia('(max-width: 700px) and (pointer: coarse)').matches;
}

// stageSize() a longtemps mesuré #stage via getBoundingClientRect() pour
// s'adapter aux deux dispositions sans dupliquer leurs seuils ici — mais
// cet appel FORCE un calcul de mise en page immédiat. Sur OpenProcessing, où
// la page charge encore une dizaine de feuilles de style externes à ce
// moment-là, ce calcul forcé pouvait tomber sur une mise en page pas encore
// stabilisée et figer un canvas beaucoup trop petit pour de bon (rien ne le
// recalculait ensuite, seul un vrai redimensionnement de fenêtre le fait).
// windowWidth/windowHeight et matchMedia() n'ont besoin d'aucune feuille de
// style : ils répondent instantanément, sans jamais forcer ce calcul.
function stageSize() {
  const collapsed = panelEl && panelEl.elt.classList.contains('collapsed');
  const mobile = isMobileLayout();
  const panelW = (!mobile && !collapsed) ? PANEL_W : 0;
  const panelH = (mobile && !collapsed) ? windowHeight * 0.3334 + 100 : 0;
  return {
    w: Math.max(240, windowWidth - panelW - STAGE_MARGIN * 2),
    h: Math.max(240, windowHeight - panelH - STAGE_MARGIN * 2)
  };
}
function resizeStage() {
  const s = stageSize();
  resizeCanvas(s.w, s.h);
}

