function buildSliders() {
  const host = panelEl.slidersHost;
  buildSection(host, 'Shape',         ['poly', 'arc', 'primitive', 'taille', 'stroke', 'clone'], false);
  buildSection(host, 'Animation',     ['rotation', 'globalRot', 'deform', 'spacing', 'delay', 'wobble', 'pulse', 'mirror'], false);
  buildSection(host, 'Color effects', COLOR_KEYS, false);
}

// Ordre effectif d'une section : l'ordre sauvegardé (filtré aux clés encore
// valides pour cette section), complété par les clés par défaut qui n'y
// figuraient pas encore (ex. un slider ajouté après coup) à leur position
// d'origine, en fin de liste.
function effectiveSliderOrder(title, defaultKeys) {
  const saved = sliderOrderPrefs[title];
  if (!Array.isArray(saved)) return defaultKeys.slice();
  const kept = saved.filter(k => defaultKeys.includes(k));
  const missing = defaultKeys.filter(k => !kept.includes(k));
  return kept.concat(missing);
}

// Construit une section repliable de sliders. Le radio Layout suit le slider
// "clone" (les deux voyagent ensemble comme un seul bloc déplaçable).
// Chaque slider peut être glissé-déposé pour changer son ordre, uniquement à
// l'intérieur de sa propre section — cf. makeSliderSlotDraggable/reorderSliderSlot.
function buildSection(host, title, keys, collapsed) {
  const byKey = {};
  SLIDER_DEFS.forEach(d => { byKey[d.key] = d; });

  const sec = createDiv('').class('subsection' + (collapsed ? ' collapsed' : '')).parent(host);
  const head = createDiv('').class('subsection-head').parent(sec);
  createSpan(title).parent(head);
  createSpan('▸').class('subsection-caret').parent(head);
  const body = createDiv('').class('subsection-body').parent(sec);
  head.mousePressed(() => sec.toggleClass('collapsed'));

  const order = effectiveSliderOrder(title, keys);
  currentSliderOrder[title] = order.slice();
  sliderSlots[title] = {};

  order.forEach(key => {
    if (!byKey[key]) return;
    const slot = createDiv('').class('slider-slot').parent(body);
    sliderSlots[title][key] = slot;
    const label = createSliderRow(byKey[key], slot);
    if (key === 'clone') {
      const rrow = createDiv('').class('row-radio').parent(slot);
      createSpan('Layout').class('row-label').parent(rrow);
      const btnGrid = createDiv('').class('layout-btns').parent(rrow);
      LAYOUTS.forEach(l => {
        const b = createButton(l.label).class('layout-btn').parent(btnGrid);
        b.mousePressed(() => setCloneMode(l.value));
        layoutButtonEls[l.value] = b;
      });
      setCloneMode('grid');
    }
    // Red/Green/Blue voyagent avec Gradient (même principe que Layout avec
    // Clone ci-dessus) : imbriqués dans son bloc, ils s'affichent juste en
    // dessous par défaut et suivent Gradient au glisser-déposer — Gradient
    // reste leur seul point d'accroche visible dans l'ordre de la section.
    if (key === 'gradient') {
      ['r', 'g', 'b'].forEach(k => createSliderRow(byKey[k], slot));
    }
    makeSliderSlotDraggable(slot, label, title, key);
  });
}
// Glisser-déposer d'un slider : dépose toujours le bloc déplacé juste AVANT le
// bloc ciblé (comportement simple et prévisible), jamais vers une autre
// section — dragover/drop n'agissent que si draggedSliderSection === title.
// Seule l'étiquette (nom du slider) sert de poignée de glisser : si le bloc
// entier était "draggable", cliquer-glisser le curseur du slider lui-même
// déclencherait ce glisser-déposer HTML5 au lieu de faire varier sa valeur.
function makeSliderSlotDraggable(slot, label, title, key) {
  label.addClass('slider-drag-handle');
  label.elt.setAttribute('draggable', 'true');
  label.elt.addEventListener('dragstart', ev => {
    draggedSliderKey = key;
    draggedSliderSection = title;
    ev.dataTransfer.effectAllowed = 'move';
    try { ev.dataTransfer.setData('text/plain', key); } catch (e) {}
    slot.addClass('dragging');
    ev.stopPropagation();
  });
  label.elt.addEventListener('dragend', () => {
    slot.removeClass('dragging');
    draggedSliderKey = null;
    draggedSliderSection = null;
    clearDropMarks();
  });
  slot.elt.addEventListener('dragover', ev => {
    if (draggedSliderSection !== title || draggedSliderKey === key) return;
    ev.preventDefault();
    ev.dataTransfer.dropEffect = 'move';
    slot.addClass('drop-hi');
  });
  slot.elt.addEventListener('dragleave', () => slot.removeClass('drop-hi'));
  slot.elt.addEventListener('drop', ev => {
    ev.preventDefault();
    ev.stopPropagation();
    slot.removeClass('drop-hi');
    if (draggedSliderSection !== title || !draggedSliderKey || draggedSliderKey === key) return;
    reorderSliderSlot(title, draggedSliderKey, key);
  });
}
function reorderSliderSlot(title, movedKey, targetKey) {
  var order = currentSliderOrder[title];
  const from = order.indexOf(movedKey);
  if (from === -1) return;
  order.splice(from, 1);
  const to = order.indexOf(targetKey);
  order.splice(to === -1 ? from : to, 0, movedKey);

  sliderOrderPrefs[title] = order.slice();
  saveSliderOrderPrefs();

  const movedEl = sliderSlots[title][movedKey].elt;
  const targetEl = sliderSlots[title][targetKey].elt;
  targetEl.parentNode.insertBefore(movedEl, targetEl);
}

function createSliderRow(def, host) {
  const row = createDiv('').class('row').parent(host);
  var label = createSpan(def.name).class('row-label').parent(row);
  var s = createSlider(def.min, def.max, def.val, def.step).parent(row);
  s.def = def;
  s.input(refreshValueSpans);
  sliders[def.key] = s;
  valueSpans[def.key] = createSpan('').class('row-value').parent(row);
  return label;
}

