// --- Historique des exports vidéo (5 derniers, session uniquement) ---
// Le fichier vit déjà sur disque (écrit par saveToProjectDir) : "Play" demande
// au serveur de l'ouvrir dans VLC plutôt que de dupliquer la vidéo en mémoire
// dans un lecteur inline — on n'a donc besoin de retenir que le nom de fichier.
const MAX_RECENT_EXPORTS = 5;
let recentExports = [];          // [filename, ...] le plus récent en premier
let recentExportsHost;

function registerRecentExport(filename) {
  recentExports.unshift(filename);
  if (recentExports.length > MAX_RECENT_EXPORTS) recentExports.length = MAX_RECENT_EXPORTS;
  renderRecentExports();
}

// Lance le fichier dans VLC via le serveur (server.py : POST /__play).
function playExportFile(filename) {
  fetch('/__play?file=' + encodeURIComponent(filename), { method: 'POST' })
    .then(res => { if (!res.ok) throw new Error('HTTP ' + res.status); })
    .catch(e => {
      console.warn('[export] lecture VLC indisponible', e);
      showToast("Impossible de lancer VLC pour ce fichier. Voir la console pour le détail.", 'error');
    });
}

// Supprime le fichier sur disque (server.py : DELETE) et retire l'entrée de la
// liste visible dans tous les cas (même si le fichier était déjà absent côté
// serveur, ex. supprimé manuellement entre-temps).
function deleteExportFile(filename) {
  fetch('/' + encodeURIComponent(filename), { method: 'DELETE' })
    .catch(e => console.warn('[export] suppression du fichier a échoué', e))
    .finally(() => {
      recentExports = recentExports.filter(f => f !== filename);
      renderRecentExports();
    });
}

function renderRecentExports() {
  recentExportsHost.html('');
  recentExports.forEach(filename => {
    var row = createDiv('').class('export-row').parent(recentExportsHost);
    createButton('▶ ' + filename).class('btn-play-export').parent(row).mousePressed(() => playExportFile(filename));
    createButton('🗑').class('lib-del').parent(row).mousePressed(() => deleteExportFile(filename));
  });
}

// Coche verte affichée quelques secondes après un export réussi (écriture
// disque ou téléchargement de repli), puis masquée. Partagée par l'export
// vidéo (à droite de "Stop & save") et l'export JSON de la bibliothèque (à
// droite de "Export") — le timer est stocké sur l'élément lui-même, pas besoin
// d'une variable globale par coche.
function flashCheck(el) {
  if (!el) return;
  el.addClass('show');
  clearTimeout(el._flashTimer);
  el._flashTimer = setTimeout(() => el.removeClass('show'), 3000);
}

// Message flottant non bloquant, en remplacement de alert() : une alerte
// native fige toute la page (mauvaise expérience pour un visiteur public sur
// OpenProcessing) et masque le canvas derrière sa pop-up. 'error' colore la
// bordure en rouge, sinon neutre (accent).
let toastEl, toastTimer;
function showToast(message, kind) {
  if (!toastEl) toastEl = createDiv('').id('toast');
  toastEl.html(message);
  toastEl.class('show' + (kind === 'error' ? ' toast-error' : ''));
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => toastEl.removeClass('show'), 4500);
}

// ============================================================================
//  EXPORT POUR OPENPROCESSING
// ============================================================================
// OpenProcessing fait tourner un éditeur de code p5.js : on y colle le JS du
// sketch (setup/draw/...), la page HTML et la librairie p5.js sont fournies
// par la plateforme — impossible d'y héberger notre index.html tel quel (balise
// <script src=cdn>, <html>/<head> propres). Ce bouton extrait donc uniquement
// le code JS (le contenu du <script id="sketch-script">) dans un fichier à
// coller dans un nouveau sketch OpenProcessing.
// Ce qui NE fonctionnera PAS là-bas, faute d'équivalent hébergé à distance :
// écriture directe des fichiers à côté d'index.html (JSON/MP4) et lecture VLC
// (server.py). Le code bascule déjà tout seul sur le téléchargement navigateur
// classique dans ces cas (voir saveToProjectDir) — c'est le maximum possible
// sur une plateforme sans serveur local.
// Le script exporté par "Export for OpenProcessing" est une copie verbatim de
// CE fichier : une fois collé là-bas, il recréerait donc les 2 boutons
// d'export ci-dessous, qui n'ont aucun sens une fois qu'on est déjà sur
// OpenProcessing. On les masque simplement quand le sketch tourne sur ce
// domaine, sans dupliquer le code source.
function isOpenProcessingHost() {
  return /openprocessing/i.test(location.hostname);
}

function buildOpenProcessingExport() {
  var host = panelEl.exportHost;
  createButton('Export for OpenProcessing').class('btn-export-op').parent(host)
    .mousePressed(exportForOpenProcessing);
  createDiv(
    'Colle le fichier téléchargé comme sketch.js d\'un nouveau sketch p5.js sur OpenProcessing. ' +
    'L\'écriture directe des fichiers et la lecture VLC ne fonctionnent que sur ce serveur local ' +
    'et basculent automatiquement sur le téléchargement classique là-bas.'
  ).class('export-op-hint').parent(host);

  createButton('Export current look (frozen)').class('btn-export-op btn-export-op-frozen').parent(host)
    .mousePressed(exportForOpenProcessingFrozen);
  createDiv(
    'Version allégée : fige l\'apparence actuelle (valeurs des sliders, pas de panneau ni de ' +
    'presets) en un script minimal, sans le code mort pour ces réglages précis. Idéal pour ' +
    'partager un seul rendu ; repasse par le bouton ci-dessus pour garder tous les contrôles.'
  ).class('export-op-hint').parent(host);
}

function exportForOpenProcessing() {
  const scriptEl = document.getElementById('sketch-script');
  if (!scriptEl) { showToast('Code source du sketch introuvable.', 'error'); return; }
  // Fige une copie de la bibliothèque courante dans le texte exporté (voir
  // EMBEDDED_LIBRARY_SEED) : sans ça, un visiteur OpenProcessing démarrerait
  // avec une bibliothèque vide (pas de localStorage ni de library.json à côté
  // du script collé), et "preset au hasard au chargement" n'aurait jamais rien
  // à tirer.
  const seedNodes = serializeLibrary();
  const presetCount = seedNodes.reduce((c, n) => c + (n.kind === 'group' ? n.presets.length : 1), 0);
  const src = scriptEl.textContent.replace(
    'const EMBEDDED_LIBRARY_SEED = null;',
    'const EMBEDDED_LIBRARY_SEED = ' + JSON.stringify(seedNodes) + ';'
  );
  var header =
    '// Exporté depuis le sketch p5.js local pour OpenProcessing.\n' +
    '// À coller comme sketch.js d\'un NOUVEAU sketch p5.js sur openprocessing.org\n' +
    '// (OpenProcessing fournit sa propre page HTML et sa propre version de p5.js :\n' +
    '// pas besoin, et pas possible, d\'y importer index.html tel quel).\n' +
    '//\n' +
    '// Bibliothèque de presets incluse : ' + presetCount + ' preset(s), figés dans ce fichier\n' +
    '// au moment de l\'export (voir EMBEDDED_LIBRARY_SEED) — un visiteur qui ouvre ce\n' +
    '// sketch sur OpenProcessing les retrouve tous de suite, avec un preset choisi\n' +
    '// au hasard au chargement, sans rien avoir à importer.\n' +
    '//\n' +
    '// Limite connue : l\'écriture directe des fichiers (export JSON/MP4 à côté\n' +
    '// d\'index.html) et la lecture VLC dépendent d\'un petit serveur local\n' +
    '// (server.py) absent d\'OpenProcessing. Le code bascule alors automatiquement\n' +
    '// sur le téléchargement navigateur classique — inévitable sur une plateforme\n' +
    '// hébergée à distance, sans accès au système de fichiers local.\n\n';
  const blob = new Blob([header + src], { type: 'text/javascript' });
  downloadBlob(blob, 'sketch_openprocessing.js');
}

// Formule de position par layout (extraite du switch de clonePos), une seule
// gardée dans l'export figé puisque cloneMode est fixe pour un rendu donné.
const FROZEN_LAYOUTS = {
  grid: {
    layoutParams: [
      'function layoutParams(n, spacing) {',
      '  const cols = Math.min(10, Math.floor(Math.sqrt(n))) || 1;',
      '  return { cols, rows: Math.ceil(n / cols) };',
      '}'
    ],
    clonePos: [
      'function clonePos(idx, n, spacing, lp) {',
      '  const c = idx % lp.cols, r = Math.floor(idx / lp.cols);',
      '  return { x: (c - (lp.cols - 1) / 2) * spacing, y: (r - (lp.rows - 1) / 2) * spacing };',
      '}'
    ]
  },
  line: {
    layoutParams: ['function layoutParams(n, spacing) { return {}; }'],
    clonePos: [
      'function clonePos(idx, n, spacing, lp) {',
      '  return { x: (idx - (n - 1) / 2) * spacing, y: 0 };',
      '}'
    ]
  },
  ring: {
    layoutParams: ['function layoutParams(n, spacing) { return { R: n > 0 ? spacing * n / (Math.PI * 2) : 0 }; }'],
    clonePos: [
      'function clonePos(idx, n, spacing, lp) {',
      '  const a = idx / n * (Math.PI * 2);',
      '  return { x: Math.cos(a) * lp.R, y: Math.sin(a) * lp.R };',
      '}'
    ]
  },
  spiral: {
    layoutParams: ['function layoutParams(n, spacing) { return {}; }'],
    clonePos: [
      'function clonePos(idx, n, spacing, lp) {',
      '  const a = idx * 0.55, r = spacing * 0.5 * Math.sqrt(idx);',
      '  return { x: Math.cos(a) * r, y: Math.sin(a) * r };',
      '}'
    ]
  },
  phyllotaxis: {
    layoutParams: ['function layoutParams(n, spacing) { return {}; }'],
    clonePos: [
      'function clonePos(idx, n, spacing, lp) {',
      '  const a = idx * 2.399963, r = spacing * 0.7 * Math.sqrt(idx);',
      '  return { x: Math.cos(a) * r, y: Math.sin(a) * r };',
      '}'
    ]
  },
  rays: {
    layoutParams: ['function layoutParams(n, spacing) { return { rayCount: Math.max(2, Math.round(Math.sqrt(n))) }; }'],
    clonePos: [
      'function clonePos(idx, n, spacing, lp) {',
      '  const TAU = Math.PI * 2;',
      '  const rc = lp.rayCount, ri = idx % rc, k = Math.floor(idx / rc);',
      '  const a = ri / rc * TAU, d = spacing * (k + 1);',
      '  return { x: Math.cos(a) * d, y: Math.sin(a) * d };',
      '}'
    ]
  },
  wave: {
    layoutParams: ['function layoutParams(n, spacing) { return {}; }'],
    clonePos: [
      'function clonePos(idx, n, spacing, lp) {',
      '  return { x: (idx - (n - 1) / 2) * spacing, y: Math.sin(idx * 0.5) * spacing * 1.5 };',
      '}'
    ]
  }
};
const FROZEN_PRIMITIVE_CALLS = { 1: 'drawTetra(1);', 2: 'box(1);', 3: 'sphere(0.6);', 4: 'cone(0.55, 1.2);', 5: 'torus(0.55, 0.22);' };

function frozenNum(n) {
  return Number.isFinite(n) ? String(n) : '0';
}

// Construit le code source d'un sketch p5.js autonome (sans panneau, sans
// bibliothèque de presets) qui reproduit exactement l'apparence ACTUELLE
// (valeurs des sliders en ce moment). Contrairement à "Export for
// OpenProcessing" (qui exporte tout index.html tel quel, sliders inclus), ce
// générateur élimine à la génération toute branche qui ne peut jamais
// s'exécuter pour CES valeurs précises (dégradé désactivé, projecteurs
// éteints, layout figé sur le seul mode actif...), d'où un fichier beaucoup
// plus court. Toute la logique de calcul reprend mot pour mot celle
// d'index.html — seules les branches mortes pour cet état sont retirées.
function buildFrozenSketchSource(state) {
  const is3D = state.primitive >= 1;
  const primKind = Math.floor(state.primitive);
  const hasBeams = state.l1 > 0 || state.l2 > 0;
  const hasGradient = state.gradient > 0;
  const hasIrid = state.irid > 0;
  const hasMirror = state.mirror > 0;
  const hasWobble = state.wobble > 0;
  const hasPulse = state.pulse > 0;
  const hasDelay = state.delay > 0;
  const hasTrails = state.trails > 0;
  const hasTint2D = hasBeams && !is3D;      // teinte 2D par faisceau (seulement en mode 2D)
  const needsHsv = hasGradient || hasIrid;
  const mode = LAYOUT_VALUES.includes(state.cloneMode) ? state.cloneMode : 'grid';
  var layout = FROZEN_LAYOUTS[mode];

  const lines = [];
  const add = (...ls) => ls.forEach(l => lines.push(l));

  add(
    '// Reproduction figée de l\'apparence actuelle (générée depuis le panneau local).',
    '// À coller comme sketch.js d\'un NOUVEAU sketch p5.js sur openprocessing.org.',
    '// Contrairement à "Export for OpenProcessing", ce fichier ne contient PLUS de',
    '// panneau ni de bibliothèque de presets : les valeurs des sliders sont figées',
    '// en constantes ci-dessous, et tout calcul qui ne peut jamais s\'exécuter pour',
    '// ces valeurs précises (effets désactivés, layout non utilisé...) a été retiré.',
    '// Pour repartir d\'un réglage différent, réexporte depuis le panneau local.',
    ''
  );

  add('const FRAMERATE = ' + FRAMERATE + ';');
  add('const SPACING_SIZE_FACTOR = ' + SPACING_SIZE_FACTOR + ';');
  if (!is3D) add('const ARC_STRENGTH = ' + ARC_STRENGTH + ';');
  add('');
  add('let angle = ' + frozenNum(state.angle) + ';');
  add('let globalAngle = ' + frozenNum(state.globalAngle) + ';');
  add('');

  const vFields = [];
  vFields.push('taille: ' + frozenNum(state.taille));
  vFields.push('stroke: ' + frozenNum(state.stroke));
  vFields.push('bgColor: ' + frozenNum(state.bgColor));
  vFields.push('r: ' + frozenNum(state.r) + ', g: ' + frozenNum(state.g) + ', b: ' + frozenNum(state.b));
  vFields.push('fill: ' + frozenNum(state.fill));
  vFields.push('alpha: ' + frozenNum(state.alpha));
  if (hasTrails) vFields.push('trails: ' + frozenNum(state.trails));
  if (hasGradient) vFields.push('gradient: ' + frozenNum(state.gradient));
  if (hasIrid) vFields.push('irid: ' + frozenNum(state.irid));
  vFields.push('rotation: ' + frozenNum(state.rotation));
  vFields.push('globalRot: ' + frozenNum(state.globalRot));
  vFields.push('clone: ' + frozenNum(state.clone));
  vFields.push('deform: ' + frozenNum(state.deform));
  vFields.push('spacing: ' + frozenNum(state.spacing));
  if (hasWobble) vFields.push('wobble: ' + frozenNum(state.wobble));
  if (hasPulse) vFields.push('pulse: ' + frozenNum(state.pulse));
  if (hasDelay) vFields.push('delay: ' + frozenNum(state.delay));
  if (hasMirror) vFields.push('mirror: ' + frozenNum(state.mirror));
  if (hasBeams) vFields.push('l1: ' + frozenNum(state.l1) + ', l2: ' + frozenNum(state.l2));
  if (!is3D) { vFields.push('poly: ' + frozenNum(state.poly)); vFields.push('arc: ' + frozenNum(state.arc)); }
  add('const V = { ' + vFields.join(', ') + ' };');
  if (!is3D) add('const CLONE_MODE = ' + JSON.stringify(mode) + '; // preset.cloneMode');
  else add('// cloneMode : ' + JSON.stringify(mode));
  add('');

  if (hasBeams) {
    add(
      '// Projecteurs actifs au moment de l\'export (position/angle/portée/cône/flou',
      '// figés) ; couleurs fixes comme dans l\'app d\'origine (chaude pour L1, froide pour L2).',
      'const beams = ['
    );
    (state.beams || []).slice(0, 2).forEach((b, i) => {
      const color = i === 0 ? '[255, 214, 170]' : '[170, 208, 255]';
      add('  { x: ' + frozenNum(b.x) + ', y: ' + frozenNum(b.y) + ', angle: ' + frozenNum(b.angle) +
        ', range: ' + frozenNum(b.range) + ', cone: ' + frozenNum(b.cone) + ', softness: ' + frozenNum(b.softness) +
        ', masked: ' + (!!b.masked) + ', color: ' + color + ' },');
    });
    add('];', '');
  }

  add(
    'function setup() {',
    '  createCanvas(windowWidth, windowHeight, WEBGL);',
    '  pixelDensity(1);',
    '  frameRate(FRAMERATE);',
    '  colorMode(RGB, 255);',
    '}',
    '',
    'function windowResized() {',
    '  resizeCanvas(windowWidth, windowHeight);',
    '}',
    ''
  );

  // ---- draw() ----
  add('function draw() {', '  const v = V;', '');
  if (hasTrails) {
    add(
      '  if (v.trails <= 0 || frameCount <= 1) background(v.bgColor);',
      '  else drawTrails(v.bgColor, v.trails);'
    );
  } else {
    add('  background(v.bgColor);');
  }
  add('', '  angle += v.rotation;', '  globalAngle += v.globalRot;', '');
  if (hasBeams) {
    add(
      '  drawingContext.disable(drawingContext.DEPTH_TEST);',
      '  drawBeamIndicators();',
      ''
    );
  }
  if (is3D) {
    add(
      '  drawingContext.enable(drawingContext.DEPTH_TEST);',
      '  setupLights();'
    );
  } else {
    add('  drawingContext.disable(drawingContext.DEPTH_TEST);');
  }
  if (hasTrails) add('  if (v.trails > 0 && frameCount > 1) drawingContext.clear(drawingContext.DEPTH_BUFFER_BIT);');
  add('');
  if (hasMirror) {
    add(
      '  const offset = map(v.mirror, 0, 100, 0, 140);',
      '  push(); translate(0, -offset); rotate(globalAngle); drawScene(v, { kind: \'top\', offset }); pop();',
      '  push(); translate(0, offset); scale(1, -1); rotate(globalAngle); drawScene(v, { kind: \'bottom\', offset }); pop();'
    );
  } else {
    add('  push(); rotate(globalAngle); drawScene(v, { kind: \'none\', offset: 0 }); pop();');
  }
  add('}', '');

  if (hasTrails) {
    add(
      'function drawTrails(bg, trails) {',
      '  const a = map(trails, 0, 100, 120, 6);',
      '  drawingContext.disable(drawingContext.DEPTH_TEST);',
      '  push();',
      '  noStroke();',
      '  fill(bg, a);',
      '  rectMode(CENTER);',
      '  rect(0, 0, width, height);',
      '  pop();',
      '}',
      ''
    );
  }

  // ---- drawScene ----
  add(
    'function drawScene(v, ctx) {',
    '  const numClones = v.clone;',
    '  const spacing = v.spacing * v.taille * SPACING_SIZE_FACTOR;',
    '  const lp = layoutParams(numClones, spacing);',
    '  const t = frameCount;',
    '  const cg = Math.cos(globalAngle), sg = Math.sin(globalAngle);',
    '',
    '  Array.from({ length: numClones }).forEach((_, idx) => {',
    '    const factor = numClones > 1 ? 1 + idx * (v.deform - 1) / (numClones - 1) : 1;',
    '    const pos = clonePos(idx, numClones, spacing, lp);',
    '',
    '    let wx = pos.x * cg - pos.y * sg;',
    '    let wy = pos.x * sg + pos.y * cg;'
  );
  if (hasMirror) {
    add(
      '    if (ctx.kind === \'top\') wy -= ctx.offset;',
      '    else if (ctx.kind === \'bottom\') wy = ctx.offset - wy;'
    );
  }
  add('    applyColors(v, idx, numClones, wx, wy);', '', '    push();', '    translate(pos.x, pos.y);', '');
  if (hasWobble) {
    add(
      '    const amp = v.wobble * 0.5;',
      '    translate((noise(idx * 0.3, t * 0.01) - 0.5) * 2 * amp,',
      '              (noise(idx * 0.3 + 99, t * 0.01) - 0.5) * 2 * amp);',
      ''
    );
  }
  add('    rotate(angle' + (hasDelay ? ' - idx * v.delay' : '') + ');', '');
  if (hasPulse) {
    add('    const pf = 1 + (v.pulse / 100) * 0.6 * sin(t * 0.08 + idx * 0.5);');
  } else {
    add('    const pf = 1;');
  }
  add('    const sz = v.taille * factor * pf;', '');
  if (is3D) {
    add('    scale(sz);', '    drawPrimitiveUnit();');
  } else {
    add('    drawShape(v.poly, sz, v.arc);');
  }
  add('    pop();', '  });', '}', '');

  add(...layout.layoutParams, '', ...layout.clonePos, '');

  // ---- applyColors ----
  add(
    '// Couleur du clone' + (needsHsv || hasTint2D ? ' (' + [
      hasGradient ? 'dégradé' : null, hasIrid ? 'iridescence' : null, hasTint2D ? 'teinte par faisceau' : null
    ].filter(Boolean).join(' + ') + ')' : ''),
    'function applyColors(v, idx, n, wx, wy) {',
    '  let cr = v.r, cg = v.g, cb = v.b;'
  );
  if (hasGradient) {
    add(
      '  if (n > 1) {',
      '    const h = (idx / n * 360 * (v.gradient / 100) * 2) % 360;',
      '    [cr, cg, cb] = hsvToRgb(h, 0.9, 0.95);',
      '  }'
    );
  }
  if (hasIrid) {
    add(
      '  {',
      '    const h = ((wx + wy) * 0.15 + angle * 220 + idx * 47) % 360;',
      '    const [ir, ig, ib] = hsvToRgb(h < 0 ? h + 360 : h, 0.6, 1);',
      '    const t = v.irid / 100;',
      '    cr = cr * (1 - t) + ir * t;',
      '    cg = cg * (1 - t) + ig * t;',
      '    cb = cb * (1 - t) + ib * t;',
      '  }'
    );
  }
  if (hasTint2D) {
    add(
      '  const L = beamLight(wx, wy);',
      '  if (L) {',
      '    cr = Math.min(255, cr * L[0]);',
      '    cg = Math.min(255, cg * L[1]);',
      '    cb = Math.min(255, cb * L[2]);',
      '  }'
    );
  }
  add(
    '  if (v.stroke > 0) { stroke(cr, cg, cb, v.alpha); strokeWeight(v.stroke); } else noStroke();',
    '  fill(cr, cg, cb, v.alpha * v.fill / 100);',
    '}',
    ''
  );

  if (needsHsv) {
    add(
      'function hsvToRgb(h, s, v) {',
      '  const c = v * s, x = c * (1 - Math.abs(((h / 60) % 2) - 1)), m = v - c;',
      '  let r = 0, g = 0, b = 0;',
      '  if (h < 60)       { r = c; g = x; }',
      '  else if (h < 120) { r = x; g = c; }',
      '  else if (h < 180) { g = c; b = x; }',
      '  else if (h < 240) { g = x; b = c; }',
      '  else if (h < 300) { r = x; b = c; }',
      '  else              { r = c; b = x; }',
      '  return [(r + m) * 255, (g + m) * 255, (b + m) * 255];',
      '}',
      ''
    );
  }

  if (is3D) {
    add(
      'function drawPrimitiveUnit() {',
      '  rotateX(angle * 1.3);',
      '  rotateY(angle * 0.9);',
      '  ' + (FROZEN_PRIMITIVE_CALLS[primKind] || 'box(1);'),
      '}',
      ''
    );
    if (primKind === 1) {
      add(
        'function drawTetra(size) {',
        '  const a = size * 0.6;',
        '  const p1 = [a, a, a], p2 = [a, -a, -a], p3 = [-a, a, -a], p4 = [-a, -a, a];',
        '  const faces = [[p1, p2, p3], [p1, p3, p4], [p1, p4, p2], [p2, p4, p3]];',
        '  beginShape(TRIANGLES);',
        '  faces.forEach(f => f.forEach(pt => vertex(pt[0], pt[1], pt[2])));',
        '  endShape();',
        '}',
        ''
      );
    }
  } else {
    add(
      'function drawShape(poly, size, arcAmount) {',
      '  const p = max(1, floor(poly));',
      '  const s = arcAmount / 100;',
      '',
      '  if (p <= 2) {',
      '    const deg = abs(s) * 360;',
      '    beginShape();',
      '    if (deg < 0.5) {',
      '      vertex(-size / 2, 0);',
      '      vertex(size / 2, 0);',
      '      endShape();',
      '    } else {',
      '      const full = deg > 359;',
      '      const span = full ? TWO_PI : radians(deg);',
      '      const N = max(12, floor(span / (PI / 24)));',
      '      Array.from({ length: N + 1 }).forEach((_, k) => {',
      '        const a = -span / 2 + span * (k / N);',
      '        vertex(cos(a) * size / 2, sin(a) * size / 2);',
      '      });',
      '      full ? endShape(CLOSE) : endShape();',
      '    }',
      '    return;',
      '  }',
      '',
      '  const pts = Array.from({ length: p }).map((_, k) => {',
      '    const a = k * TWO_PI / p;',
      '    return { x: cos(a) * size, y: sin(a) * size };',
      '  });',
      '  const SEG = max(2, round(2 + abs(s) * 10));',
      '',
      '  beginShape();',
      '  vertex(pts[0].x, pts[0].y);',
      '  Array.from({ length: p }).forEach((_, i) => {',
      '    const A = pts[i];',
      '    const B = pts[(i + 1) % p];',
      '    const mx = (A.x + B.x) / 2, my = (A.y + B.y) / 2;',
      '    const r = Math.hypot(mx, my) || 1;',
      '    const nx = mx / r, ny = my / r;',
      '    const edgeLen = Math.hypot(B.x - A.x, B.y - A.y);',
      '    const off = s * edgeLen * ARC_STRENGTH;',
      '    const cx = mx + nx * off, cy = my + ny * off;',
      '    Array.from({ length: SEG }).forEach((__, j) => {',
      '      const tt = (j + 1) / SEG, it = 1 - tt;',
      '      vertex(it * it * A.x + 2 * it * tt * cx + tt * tt * B.x,',
      '             it * it * A.y + 2 * it * tt * cy + tt * tt * B.y);',
      '    });',
      '  });',
      '  endShape(CLOSE);',
      '}',
      ''
    );
  }

  if (hasBeams) {
    add(
      'function beamExtents(b) {',
      '  const soft = b.softness || 0;',
      '  return {',
      '    innerCone: b.cone * 0.55,',
      '    outerCone: b.cone * (1 + soft * 1.8),',
      '    innerRange: b.range * 0.55,',
      '    outerRange: b.range * (1 + soft * 1.2)',
      '  };',
      '}',
      '',
      'function beamFalloff(da, dist, ext) {',
      '  const angFall = da <= ext.innerCone ? 1',
      '    : da >= ext.outerCone ? 0',
      '    : 1 - (da - ext.innerCone) / (ext.outerCone - ext.innerCone);',
      '  const distFall = dist <= ext.innerRange ? 1',
      '    : dist >= ext.outerRange ? 0',
      '    : 1 - (dist - ext.innerRange) / (ext.outerRange - ext.innerRange);',
      '  return angFall * distFall;',
      '}',
      ''
    );
    if (!is3D) {
      add(
        'function beamLight(wx, wy) {',
        '  const inten = [V.l1 / 100, V.l2 / 100];',
        '  let ar = ' + BEAM_AMBIENT + ', ag = ' + BEAM_AMBIENT + ', ab = ' + BEAM_AMBIENT + ';',
        '  beams.forEach((b, i) => {',
        '    const k = inten[i];',
        '    if (k <= 0) return;',
        '    const dx = wx - b.x, dy = wy - b.y;',
        '    const dist = Math.hypot(dx, dy);',
        '    let da = Math.atan2(dy, dx) - b.angle;',
        '    da = Math.abs(Math.atan2(Math.sin(da), Math.cos(da)));',
        '    const ext = beamExtents(b);',
        '    if (da > ext.outerCone || dist > ext.outerRange) return;',
        '    const c = k * beamFalloff(da, dist, ext);',
        '    ar += c * b.color[0] / 255; ag += c * b.color[1] / 255; ab += c * b.color[2] / 255;',
        '  });',
        '  return [ar, ag, ab];',
        '}',
        ''
      );
    }
    add(
      'function drawBeamIndicators() {',
      '  const inten = [V.l1 / 100, V.l2 / 100];',
      '  drawingContext.disable(drawingContext.DEPTH_TEST);',
      '  beams.forEach((b, i) => {',
      '    const k = inten[i];',
      '    if (k <= 0 || b.masked) return;',
      '    const ext = beamExtents(b);',
      '    push();',
      '    translate(b.x, b.y);',
      '    rotate(b.angle);',
      '    noStroke();',
      '    const ANGLE_STEPS = 10, DIST_STEPS = 10;',
      '    Array.from({ length: ANGLE_STEPS }).forEach((_, ai) => {',
      '      const a0 = -ext.outerCone + (2 * ext.outerCone) * (ai / ANGLE_STEPS);',
      '      const a1 = -ext.outerCone + (2 * ext.outerCone) * ((ai + 1) / ANGLE_STEPS);',
      '      const aMid = Math.abs((a0 + a1) / 2);',
      '      Array.from({ length: DIST_STEPS }).forEach((__, di) => {',
      '        const r0 = ext.outerRange * (di / DIST_STEPS);',
      '        const r1 = ext.outerRange * ((di + 1) / DIST_STEPS);',
      '        const fall = beamFalloff(aMid, (r0 + r1) / 2, ext);',
      '        if (fall <= 0.02) return;',
      '        fill(b.color[0], b.color[1], b.color[2], 55 * k * fall);',
      '        beginShape();',
      '        vertex(r0 * Math.cos(a0), r0 * Math.sin(a0));',
      '        vertex(r1 * Math.cos(a0), r1 * Math.sin(a0));',
      '        vertex(r1 * Math.cos(a1), r1 * Math.sin(a1));',
      '        vertex(r0 * Math.cos(a1), r0 * Math.sin(a1));',
      '        endShape(CLOSE);',
      '      });',
      '    });',
      '    pop();',
      '  });',
      '}',
      ''
    );
  }

  if (is3D) {
    add(
      'function setupLights() {',
      '  ambientLight(70);',
      '  directionalLight(80, 80, 80, 0.3, 0.4, -1);'
    );
    if (hasBeams) {
      add(
        '  const inten = [V.l1 / 100, V.l2 / 100];',
        '  beams.forEach((b, i) => {',
        '    const k = inten[i];',
        '    if (k <= 0) return;',
        '    const px = b.x, py = b.y, pz = 260;',
        '    const tx = b.x + Math.cos(b.angle) * b.range * 0.5;',
        '    const ty = b.y + Math.sin(b.angle) * b.range * 0.5;',
        '    let dx = tx - px, dy = ty - py, dz = -pz;',
        '    const dl = Math.hypot(dx, dy, dz) || 1;',
        '    const ext = beamExtents(b);',
        '    const conc = 40 - (b.softness || 0) * 37;',
        '    spotLight(b.color[0] * k, b.color[1] * k, b.color[2] * k,',
        '              px, py, pz, dx / dl, dy / dl, dz / dl,',
        '              Math.min(1.45, ext.outerCone), Math.max(2, conc));',
        '  });'
      );
    }
    add('}', '');
  }

  return lines.join('\n');
}

function exportForOpenProcessingFrozen() {
  const state = readCurrentState();
  var src = buildFrozenSketchSource(state);
  var blob = new Blob([src], { type: 'text/javascript' });
  downloadBlob(blob, 'sketch_openprocessing_frozen.js');
}

// ============================================================================
//  AFFICHAGE DES VALEURS
// ============================================================================
function refreshValueSpans() {
  // Red/Green/Blue sont écrasés par la teinte du dégradé dès que gradient > 0
  // (voir drawScene() : cr/cg/cb sont recalculés depuis v.gradient, la couleur
  // RGB fixe n'est alors plus utilisée). Plutôt que les masquer, on les
  // désactive (verrouillés, pas de display:none) et on fait suivre leur
  // curseur en direct sur une teinte dérivée de gradient (via hsvToRgb(),
  // déjà utilisée par drawScene() pour ce même dégradé) : on VOIT ainsi les
  // trois curseurs bouger pendant qu'on glisse Gradient, sans pouvoir les
  // déplacer soi-même en même temps (ce qui romprait aussitôt la synchro).
  // Aperçu simplifié à une seule teinte : le rendu réel varie aussi par index
  // de clone (voir drawScene()), ce qu'un seul triplet RGB ne peut pas capter.
  const gradientOn = sliders.gradient.value() > 0;
  if (gradientOn) {
    const [rr, gg, bb] = hsvToRgb((sliders.gradient.value() / 100) * 360, 1, 1);
    sliders.r.value(Math.round(rr));
    sliders.g.value(Math.round(gg));
    sliders.b.value(Math.round(bb));
  }
  ['r', 'g', 'b'].forEach(k => {
    if (gradientOn) sliders[k].attribute('disabled', ''); else sliders[k].removeAttribute('disabled');
  });
  SLIDER_KEYS.forEach(key => {
    valueSpans[key].html(formatValue(sliders[key].value(), sliders[key].def.step));
  });
}
function formatValue(v, step) {
  if (step >= 1) return String(v);
  const decimals = (String(step).split('.')[1] || '').length || 2;
  return Number(v).toFixed(decimals);
}

// ============================================================================
//  DRAW
// ============================================================================
function draw() {
  const v = {};
  SLIDER_KEYS.forEach(k => { v[k] = sliders[k].value(); });

  // Fond ou traînées
  if (v.trails <= 0 || frameCount <= 1) background(v.bgColor);
  else drawTrails(v.bgColor, v.trails);

  angle += v.rotation;
  globalAngle += v.globalRot;

  // Contrôle caméra à la souris : glisser pivote (tous sens), molette zoome,
  // clic droit/Ctrl+glisser fait un panoramique. Coupé pendant qu'un projecteur
  // est en cours de glisser (dragBeam) pour ne pas faire bouger la caméra sous
  // la poignée qu'on est en train d'éditer — voir positionBeamHandles(), qui
  // reprojette les poignées avec screenX/screenY pour rester alignées.
  // isOverCanvas() : orbitControl() ne se limite pas tout seul au canvas (testé
  // en pratique — un glisser démarré sur un slider du panneau faisait aussi
  // pivoter la caméra), d'où cette garde explicite.
  if (!dragBeam && isOverCanvas()) orbitControl();

  var is3D = v.primitive >= 1;

  // 1) Cônes de faisceau DERRIÈRE la scène (sans profondeur) → un cube opaque les masque
  drawingContext.disable(drawingContext.DEPTH_TEST);
  drawBeamIndicators();

  // 2) Profondeur + lumières pour les clones
  if (is3D) {
    drawingContext.enable(drawingContext.DEPTH_TEST);
    setupLights3D(v);   // ambiance douce + vrais projecteurs (spotLight) des faisceaux
  } else {
    drawingContext.disable(drawingContext.DEPTH_TEST);
  }
  if (v.trails > 0 && frameCount > 1) drawingContext.clear(drawingContext.DEPTH_BUFFER_BIT);

  // Origine déjà au centre en WEBGL : plus de translate(width/2, height/2)
  if (v.mirror > 0) {
    const offset = map(v.mirror, 0, 100, 0, 140);
    push(); translate(0, -offset); rotate(globalAngle); drawScene(v, { kind: 'top', offset }); pop();
    push(); translate(0, offset); scale(1, -1); rotate(globalAngle); drawScene(v, { kind: 'bottom', offset }); pop();
  } else {
    push(); rotate(globalAngle); drawScene(v, { kind: 'none', offset: 0 }); pop();
  }

  positionBeamHandles();     // poignées L1/L2 suivent le canvas

  if (recording) {
    recordFrames++;
    timeDisplay.html('Duration: ' + nf(recordFrames / FRAMERATE, 1, 1) + ' s');
  }

  // Vignette de preset : capturée ici, en fin de rendu (tampon encore valide)
  if (pendingThumbPreset) {
    captureThumb(pendingThumbPreset);
    pendingThumbPreset = null;
  }
}

// Rectangle plein écran semi-transparent → effet de traînées (persistance)
function drawTrails(bg, trails) {
  const a = map(trails, 0, 100, 120, 6);
  drawingContext.disable(drawingContext.DEPTH_TEST);
  push();
  // Recadre temporairement sur la caméra par défaut (formule interne de p5,
  // annulée par pop() juste après) : sinon ce rectangle plein écran est vu
  // depuis la caméra ACTUELLE (orbitControl peut l'avoir tournée/zoomée) et ne
  // recouvre plus tout l'écran, laissant l'image précédente visible en trace.
  camera(0, 0, (height / 2) / Math.tan(PI / 6), 0, 0, 0, 0, 1, 0);
  noStroke();
  fill(bg, a);
  rectMode(CENTER);
  rect(0, 0, width, height);
  pop();
}

// Dessine le champ de clones. forEach partout (le protecteur anti-boucle de
// l'éditeur p5 n'instrumente que for/while).
function drawScene(v, ctx) {
  const numClones = v.clone;
  // L'espacement suit la taille des clones (rayon ≈ v.taille) : à spacing=1 les
  // bords se touchent tout juste (2×taille = diamètre). Sans ce facteur, des
  // clones plus grands que l'écart fixe se chevauchent en bloc quel que soit le
  // layout choisi — la disposition change bien les centres, mais des formes trop
  // grandes pour cet écart masquent complètement la différence entre layouts.
  const spacing = v.spacing * v.taille * SPACING_SIZE_FACTOR;
  var mode = getMode();
  const lp = layoutParams(mode, numClones, spacing);
  const t = frameCount;
  const cg = Math.cos(globalAngle), sg = Math.sin(globalAngle);

  Array.from({ length: numClones }).forEach((_, idx) => {
    const factor = numClones > 1 ? 1 + idx * (v.deform - 1) / (numClones - 1) : 1;
    const pos = clonePos(mode, idx, numClones, spacing, lp);

    // Position MONDE du clone (pour l'éclairage) : rotation globale + miroir
    let wx = pos.x * cg - pos.y * sg;
    let wy = pos.x * sg + pos.y * cg;
    if (ctx.kind === 'top') wy -= ctx.offset;
    else if (ctx.kind === 'bottom') wy = ctx.offset - wy;
    applyColors(v, idx, numClones, wx, wy);

    push();
    translate(pos.x, pos.y);

    // Ondulation Perlin : décalage organique par clone
    if (v.wobble > 0) {
      const amp = v.wobble * 0.5;
      translate((noise(idx * 0.3, t * 0.01) - 0.5) * 2 * amp,
                (noise(idx * 0.3 + 99, t * 0.01) - 0.5) * 2 * amp);
    }

    rotate(angle - idx * v.delay);

    // Pulsation : taille modulée par un sinus
    const pf = v.pulse > 0 ? 1 + (v.pulse / 100) * 0.6 * sin(t * 0.08 + idx * 0.5) : 1;
    const sz = v.taille * factor * pf;

    if (v.primitive >= 1) {
      scale(sz);
      drawPrimitiveUnit(floor(v.primitive));       // primitive native, taille 1 mise à l'échelle
    } else {
      drawShape(v.poly, sz, v.arc);                // mode immédiat (contour + remplissage corrects)
    }
    pop();
  });
}

// Paramètres de layout précalculés une fois par frame
function layoutParams(mode, n, spacing) {
  if (mode === 'grid') {
    const cols = Math.min(10, Math.floor(Math.sqrt(n))) || 1;
    return { cols, rows: Math.ceil(n / cols) };
  }
  if (mode === 'ring')  return { R: n > 0 ? spacing * n / (Math.PI * 2) : 0 };
  if (mode === 'rays')  return { rayCount: Math.max(2, Math.round(Math.sqrt(n))) };
  return {};
}

// Position (x,y) d'un clone selon le layout — calcul pur (testé en isolation)
function clonePos(mode, idx, n, spacing, lp) {
  const TAU = Math.PI * 2;
  switch (mode) {
    case 'line':
      return { x: (idx - (n - 1) / 2) * spacing, y: 0 };
    case 'ring': {
      var a = idx / n * TAU;
      return { x: Math.cos(a) * lp.R, y: Math.sin(a) * lp.R };
    }
    case 'spiral': {
      var a = idx * 0.55, r = spacing * 0.5 * Math.sqrt(idx);
      return { x: Math.cos(a) * r, y: Math.sin(a) * r };
    }
    case 'phyllotaxis': {
      var a = idx * 2.399963, r = spacing * 0.7 * Math.sqrt(idx);  // angle d'or ≈ 137,5°
      return { x: Math.cos(a) * r, y: Math.sin(a) * r };
    }
    case 'rays': {
      const rc = lp.rayCount, ri = idx % rc, k = Math.floor(idx / rc);
      var a = ri / rc * TAU, d = spacing * (k + 1);
      return { x: Math.cos(a) * d, y: Math.sin(a) * d };
    }
    case 'wave':
      return { x: (idx - (n - 1) / 2) * spacing, y: Math.sin(idx * 0.5) * spacing * 1.5 };
    case 'grid':
    default: {
      const c = idx % lp.cols, r = Math.floor(idx / lp.cols);
      return { x: (c - (lp.cols - 1) / 2) * spacing, y: (r - (lp.rows - 1) / 2) * spacing };
    }
  }
}

// Couleur du clone (dégradé de teinte optionnel le long des clones).
// Conversion HSV→RGB manuelle : évite de basculer colorMode 200×/frame.
function applyColors(v, idx, n, wx, wy) {
  let cr = v.r, cg = v.g, cb = v.b;
  if (v.gradient > 0 && n > 1) {
    const h = (idx / n * 360 * (v.gradient / 100) * 2) % 360;
    [cr, cg, cb] = hsvToRgb(h, 0.9, 0.95);
  }
  // Iridescence : reflet façon bulle de savon qui glisse sur la surface selon
  // sa position et l'angle courant (donc animé), mélangé à la couleur de base.
  if (v.irid > 0) {
    var h = ((wx + wy) * 0.15 + angle * 220 + idx * 47) % 360;
    const [ir, ig, ib] = hsvToRgb(h < 0 ? h + 360 : h, 0.6, 1);
    var t = v.irid / 100;
    cr = cr * (1 - t) + ir * t;
    cg = cg * (1 - t) + ig * t;
    cb = cb * (1 - t) + ib * t;
  }
  // Éclairage : teinte 2D par faisceau (les primitives 3D ont de vrais spotLight)
  if (v.primitive < 1) {
    const L = beamLight(wx, wy);
    if (L) {
      cr = Math.min(255, cr * L[0]);
      cg = Math.min(255, cg * L[1]);
      cb = Math.min(255, cb * L[2]);
    }
  }
  if (v.stroke > 0) { stroke(cr, cg, cb, v.alpha); strokeWeight(v.stroke); } else noStroke();
  fill(cr, cg, cb, v.alpha * v.fill / 100);
}

function hsvToRgb(h, s, v) {
  var c = v * s, x = c * (1 - Math.abs(((h / 60) % 2) - 1)), m = v - c;
  let r = 0, g = 0, b = 0;
  if (h < 60)       { r = c; g = x; }
  else if (h < 120) { r = x; g = c; }
  else if (h < 180) { g = c; b = x; }
  else if (h < 240) { g = x; b = c; }
  else if (h < 300) { r = x; b = c; }
  else              { r = c; b = x; }
  return [(r + m) * 255, (g + m) * 255, (b + m) * 255];
}

// Primitives 3D à taille unitaire (1=tétraèdre, 2=cube, 3=sphère, 4=cône, 5=tore).
// Paramètres fixes → p5 met en cache une seule géométrie par primitive (l'appelant
// applique scale(sz)).
function drawPrimitiveUnit(kind) {
  rotateX(angle * 1.3);
  rotateY(angle * 0.9);
  if (kind === 1) drawTetra(1);
  else if (kind === 2) box(1);
  else if (kind === 3) sphere(0.6);
  else if (kind === 4) cone(0.55, 1.2);
  else if (kind === 5) torus(0.55, 0.22);
}

// Tétraèdre régulier (pas de primitive native)
function drawTetra(size) {
  var a = size * 0.6;
  const p1 = [a, a, a], p2 = [a, -a, -a], p3 = [-a, a, -a], p4 = [-a, -a, a];
  const faces = [[p1, p2, p3], [p1, p3, p4], [p1, p4, p2], [p2, p4, p3]];
  beginShape(TRIANGLES);
  faces.forEach(f => f.forEach(pt => vertex(pt[0], pt[1], pt[2])));
  endShape();
}

// Ampleur du renflement de l'arc. 1 = demi-cercle par côté à ±100 (max propre).
// Monte cette valeur (2, 3…) pour des déformations concaves/convexes extrêmes
// (pétales qui bouclent, étoiles qui se recroquevillent).
const ARC_STRENGTH = 1.0;

function drawShape(poly, size, arcAmount) {
  const p = max(1, floor(poly));
  var s = arcAmount / 100; // -1..1

  // Trait (1–2 côtés) : droit → arc → cercle complet. Échantillonné en vertex
  // (line/arc/ellipse peu fiables en WEBGL).
  if (p <= 2) {
    const deg = abs(s) * 360;
    beginShape();
    if (deg < 0.5) {
      vertex(-size / 2, 0);
      vertex(size / 2, 0);
      endShape();
    } else {
      const full = deg > 359;
      const span = full ? TWO_PI : radians(deg);
      const N = max(12, floor(span / (PI / 24)));
      Array.from({ length: N + 1 }).forEach((_, k) => {
        var a = -span / 2 + span * (k / N);
        vertex(cos(a) * size / 2, sin(a) * size / 2);
      });
      full ? endShape(CLOSE) : endShape();
    }
    return;
  }

  // Polygone : chaque côté se bombe (convexe s>0 / concave s<0), Bézier
  // quadratique échantillonnée en segments (compatible WEBGL).
  const pts = Array.from({ length: p }).map((_, k) => {
    var a = k * TWO_PI / p;
    return { x: cos(a) * size, y: sin(a) * size };
  });
  // Moins de segments quand la courbure est faible (gain perf, invisible à l'œil)
  const SEG = max(2, round(2 + abs(s) * 10));

  beginShape();
  vertex(pts[0].x, pts[0].y);
  Array.from({ length: p }).forEach((_, i) => {
    const A = pts[i];
    const B = pts[(i + 1) % p];
    const mx = (A.x + B.x) / 2, my = (A.y + B.y) / 2;
    var r = Math.hypot(mx, my) || 1;
    const nx = mx / r, ny = my / r;               // normale radiale (extérieur)
    const edgeLen = Math.hypot(B.x - A.x, B.y - A.y);
    const off = s * edgeLen * ARC_STRENGTH;       // à |s|=1 → apex ≈ demi-cercle
    const cx = mx + nx * off, cy = my + ny * off; // point de contrôle
    Array.from({ length: SEG }).forEach((__, j) => {
      const tt = (j + 1) / SEG, it = 1 - tt;
      vertex(it * it * A.x + 2 * it * tt * cx + tt * tt * B.x,
             it * it * A.y + 2 * it * tt * cy + tt * tt * B.y);
    });
  });
  endShape(CLOSE);
}

// ============================================================================
//  SÉLECTEUR DE LAYOUT (boutons)
// ============================================================================
function setCloneMode(val) {
  cloneModeValue = LAYOUT_VALUES.includes(val) ? val : 'grid';
  LAYOUT_VALUES.forEach(v => {
    const btn = layoutButtonEls[v];
    if (!btn) return;
    if (v === cloneModeValue) btn.addClass('active'); else btn.removeClass('active');
  });
}
function getMode() {
  return cloneModeValue;
}

// ============================================================================
//  PRESETS
// ============================================================================
function readCurrentState() {
  var state = {};
  SLIDER_KEYS.forEach(k => { state[k] = sliders[k].value(); });
  state.cloneMode = getMode();
  // Phase de rotation courante → preset reproductible d'un environnement à l'autre
  state.angle = angle;
  state.globalAngle = globalAngle;
  // Position/orientation/portée/cône/masquage des projecteurs
  state.beams = beams.map(b => ({ x: b.x, y: b.y, angle: b.angle, range: b.range, cone: b.cone, softness: b.softness, masked: b.masked }));
  return state;
}
function applyState(state) {
  // Un paramètre absent du preset (ex : ancien JSON exporté avant l'ajout
  // d'un nouveau slider) retombe sur sa valeur par défaut plutôt que de
  // garder la valeur actuellement affichée (qui vient du preset précédent).
  SLIDER_KEYS.forEach(k => {
    sliders[k].value(state[k] !== undefined ? state[k] : sliders[k].def.val);
  });
  if (state.cloneMode) setCloneMode(state.cloneMode);
  if (typeof state.angle === 'number') angle = state.angle;
  if (typeof state.globalAngle === 'number') globalAngle = state.globalAngle;
  // Un preset ne mémorise pas la caméra (orbitControl), donc si elle a été
  // tournée/zoomée à la souris avant de changer de preset, elle restait
  // décalée : les poignées de projecteur (qui supposent la vue par défaut,
  // voir positionBeamHandles()) semblaient alors ne plus correspondre au
  // faisceau réellement dessiné, alors que rien n'est cassé, la caméra était
  // juste restée dans un état différent d'un preset à l'autre. On la
  // réinitialise donc explicitement à chaque changement de preset.
  camera(0, 0, (height / 2) / Math.tan(PI / 6), 0, 0, 0, 0, 1, 0);
  if (Array.isArray(state.beams)) {
    state.beams.forEach((sb, i) => {
      if (beams[i] && sb) {
        beams[i].x = sb.x; beams[i].y = sb.y; beams[i].angle = sb.angle;
        if (typeof sb.range === 'number') beams[i].range = sb.range;
        if (typeof sb.cone === 'number') beams[i].cone = sb.cone;
        beams[i].softness = (typeof sb.softness === 'number') ? sb.softness : 0.3;
        beams[i].masked = !!sb.masked;
      }
    });
  }
  refreshValueSpans();
}
// ---------------------------------------------------------------------------
//  BIBLIOTHÈQUE : presets, groupes (1 niveau), glisser-déposer
// ---------------------------------------------------------------------------
// Plus petit numéro "Preset N" pas déjà pris — pas juste (nombre total de
// presets)+1, qui finit par générer des doublons dès qu'un preset au milieu de
// la liste a été supprimé (le total redescend, un futur ajout retombe sur un
// numéro déjà pris par un preset existant plus loin dans la liste).
function nextPresetName() {
  const used = new Set(Object.values(presetById).map(p => p.name));
  let n = 1;
  while (used.has('Preset ' + n)) n++;
  return 'Preset ' + n;
}
function newPreset(state) {
  var p = { kind: 'preset', uid: uidSeq++, name: nextPresetName(), thumb: '', video: '', state };
  presetById[p.uid] = p;
  return p;
}
function newGroup(name) {
  const g = { kind: 'group', gid: gidSeq++, name: name || 'Group', collapsed: false, presets: [] };
  groupById[g.gid] = g;
  return g;
}
// Groupe contenant ce preset, ou null si le preset est à la racine (pas de groupe).
function findGroupOfPreset(uid) {
  let found = null;
  libItems.forEach(n => {
    if (found) return;
    if (n.kind === 'group' && n.presets.some(p => p.uid === uid)) found = n;
  });
  return found;
}
// Localise un node → { node, arr, idx } (arr = libItems ou group.presets)
function locate(kind, id) {
  var found = null;
  libItems.forEach((n, i) => {
    if (found) return;
    if (n.kind === kind && (n.uid === id || n.gid === id)) { found = { node: n, arr: libItems, idx: i }; return; }
    if (n.kind === 'group') {
      const j = n.presets.findIndex(p => kind === 'preset' && p.uid === id);
      if (j >= 0) found = { node: n.presets[j], arr: n.presets, idx: j };
    }
  });
  return found;
}

// --- Ajout ---
// Nouveaux presets ajoutés en fin de libItems (tout en bas de la liste) : avec
// .lib-list limitée en hauteur, ils restent invisibles sans défiler manuellement
// dès qu'il y a déjà plusieurs presets. On scrolle donc vers le bas juste après
// le rendu.
function scrollLibListToBottom() {
  libListEl.elt.scrollTop = libListEl.elt.scrollHeight;
}
function addToLibrary() {
  var p = newPreset(readCurrentState());
  libItems.push(p);
  pendingThumbPreset = p;
  rebuildLibList();
  scrollLibListToBottom();
  saveLibrary();
  recordPresetVideo(p);
}
// Réécrit dans le preset actuellement sélectionné les réglages actuels des
// sliders (contrairement à "Add preset", qui crée un doublon au lieu d'écraser
// l'existant). saveLibrary() sérialise systématiquement TOUTE la bibliothèque,
// donc rien n'est perdu pour les autres presets même si un seul a changé.
function saveSelectedPresetState() {
  if (!selectedUid) { showToast('Aucun preset sélectionné.'); return; }
  var p = presetById[selectedUid];
  if (!p) return;
  p.state = readCurrentState();
  pendingThumbPreset = p; // vignette recapturée au prochain frame pour refléter le nouveau réglage
  rebuildLibList();
  saveLibrary();
  recordPresetVideo(p);
  flashCheck(savePresetCheckEl);
}
// Les groupes, eux, sont ajoutés en TÊTE de liste (plus facile à repérer tout
// de suite qu'un preset de plus parmi d'autres) : on scrolle donc vers le haut
// plutôt que vers le bas.
function addGroup() {
  libItems.unshift(newGroup());
  rebuildLibList();
  libListEl.elt.scrollTop = 0;
  saveLibrary();
}

// --- Vidéo animée (5 s), session uniquement ---
function recordPresetVideo(preset) {
  if (libBusy || typeof MediaRecorder === 'undefined') return;
  libBusy = true;
  const mimeType = 'video/webm';
  let rec;
  try { rec = new MediaRecorder(cnv.elt.captureStream(FRAMERATE), { mimeType }); }
  catch (e) { libBusy = false; return; }
  const chunks = [];
  rec.ondataavailable = e => { if (e.data.size > 0) chunks.push(e.data); };
  rec.onstop = () => {
    preset.video = URL.createObjectURL(new Blob(chunks, { type: mimeType }));
    rebuildLibList();
    libBusy = false;
  };
  rec.start();
  let f = 0;
  const timer = setInterval(() => {
    if (++f > 5 * FRAMERATE) { clearInterval(timer); if (rec.state === 'recording') rec.stop(); }
  }, 1000 / FRAMERATE);
}

// --- Export sélectif ---
// Bascule l'affichage des cases à cocher sur chaque groupe et chaque preset
// racine ; en sortant du mode, la sélection est oubliée (le bouton "Export
// all" repasse alors à un export de la bibliothèque entière).
function toggleSelectExportMode() {
  selectExportMode = !selectExportMode;
  selectExportBtn.html(selectExportMode ? 'Cancel selection' : 'Select export');
  if (selectExportMode) selectExportBtn.addClass('active'); else selectExportBtn.removeClass('active');
  if (!selectExportMode) { selectedGroupGids.clear(); selectedPresetUids.clear(); }
  updateExportButtonLabel();
  rebuildLibList();
}
// "Export selected" dès qu'au moins un groupe ou un preset racine est coché,
// sinon "Export all" (l'action exporte alors la bibliothèque entière).
function updateExportButtonLabel() {
  const hasSelection = selectedGroupGids.size > 0 || selectedPresetUids.size > 0;
  exportAllBtn.html(hasSelection ? 'Export selected JSON' : 'Export all JSON');
}

// --- Rendu ---
function rebuildLibList() {
  // Vider/reconstruire la liste remet le scroll à 0 par défaut (perte de
  // repère à chaque clic sur un preset) : on le restaure donc explicitement.
  // Les appelants qui veulent une position précise (ajout tout en bas/en haut)
  // le font déjà eux-mêmes juste après cet appel, ce qui prime naturellement.
  const scrollTop = libListEl.elt.scrollTop;
  libListEl.html('');
  libItems.forEach(node => {
    if (node.kind === 'group') renderGroup(node);
    else renderPresetRow(node, libListEl);
  });
  const end = createDiv('▁ drop here for top level ▁').class('lib-root-drop').parent(libListEl);
  makeDropTarget(end, () => { const d = pullDragged(); if (d) libItems.push(d); finalizeDrop(); });
  libListEl.elt.scrollTop = scrollTop;
}

function renderPresetRow(preset, parentEl) {
  var row = createDiv('').class('lib-item' + (preset.uid === selectedUid ? ' selected' : '')).parent(parentEl);
  makeDraggable(row, 'preset', preset.uid);
  makeDropTarget(row, () => dropOnPreset(preset.uid, row.elt));

  // La case n'apparaît que pour les presets à la racine (pas ceux déjà dans un
  // groupe, qui suivent automatiquement la case de leur groupe) — cocher un
  // preset imbriqué individuellement n'aurait aucun effet sur l'export.
  if (selectExportMode && !findGroupOfPreset(preset.uid)) {
    const cb = createElement('input').class('lib-export-check').parent(row);
    cb.attribute('type', 'checkbox');
    cb.elt.setAttribute('draggable', 'false');
    cb.elt.checked = selectedPresetUids.has(preset.uid);
    cb.elt.addEventListener('click', ev => ev.stopPropagation());
    cb.elt.addEventListener('change', () => {
      if (cb.elt.checked) selectedPresetUids.add(preset.uid); else selectedPresetUids.delete(preset.uid);
      updateExportButtonLabel();
    });
  }

  createSpan('⠿').class('lib-grip').parent(row);

  let media;
  if (preset.video) {
    media = createElement('video').class('lib-thumb').parent(row);
    media.elt.muted = true; media.elt.loop = true; media.elt.playsInline = true;
    media.attribute('src', preset.video);
    media.elt.play().catch(() => {});
  } else {
    media = createDiv('').class('lib-thumb').parent(row);
    if (preset.thumb) media.style('background-image', 'url(' + preset.thumb + ')');
  }
  // 'click' plutôt que mousePressed() de p5 (qui écoute 'mousedown') : mousedown
  // se déclenche dès qu'on pose le clic sur la vignette, soit exactement le
  // geste utilisé pour démarrer un glisser-déposer — ça sélectionnait le preset
  // avant même que le navigateur ne reconnaisse le drag, rendant tout
  // drag-and-drop depuis la vignette impossible. 'click' ne se déclenche pas
  // si un vrai drag a eu lieu entre les deux, donc il n'interfère plus.
  media.elt.addEventListener('click', () => selectPreset(preset.uid));

  const nameIn = createInput(preset.name).class('lib-name').parent(row);
  nameIn.elt.setAttribute('draggable', 'false');
  // Double-clic = tout sélectionner (pas juste le mot sous le curseur, comme le
  // ferait un double-clic natif) : taper immédiatement après remplace le nom
  // entier au lieu de l'insérer au milieu.
  nameIn.elt.addEventListener('dblclick', () => nameIn.elt.select());
  nameIn.input(() => {
    preset.name = nameIn.value();
    if (preset.uid === selectedUid) libTrigger.html(preset.name || 'Preset');
    saveLibrary();
  });

  // 'click' pour la même raison que la vignette ci-dessus : ce bouton vit dans
  // une ligne draggable, mousePressed (mousedown) se déclencherait dès la prise
  // en main pour démarrer un drag.
  createButton('🗑').class('lib-del').parent(row).elt.addEventListener('click', () => deletePreset(preset.uid));
}

function renderGroup(group) {
  var g = createDiv('').class('lib-group' + (group.collapsed ? ' collapsed' : '')).parent(libListEl);

  var head = createDiv('').class('lib-group-head').parent(g);
  makeDraggable(head, 'group', group.gid);
  makeDropTarget(head, () => dropOnGroupHead(group.gid, head.elt));

  if (selectExportMode) {
    var cb = createElement('input').class('lib-export-check').parent(head);
    cb.attribute('type', 'checkbox');
    cb.elt.setAttribute('draggable', 'false');
    cb.elt.checked = selectedGroupGids.has(group.gid);
    cb.elt.addEventListener('click', ev => ev.stopPropagation());
    cb.elt.addEventListener('change', () => {
      if (cb.elt.checked) selectedGroupGids.add(group.gid); else selectedGroupGids.delete(group.gid);
      updateExportButtonLabel();
    });
  }

  createSpan('⠿').class('lib-grip').parent(head);
  const caret = createSpan(group.collapsed ? '▸' : '▾').class('lib-group-caret').parent(head);
  // 'click' plutôt que mousePressed() de p5 : l'en-tête entier est draggable
  // (makeDraggable ci-dessus) ; en mousedown, saisir l'en-tête près du caret
  // pour le faire glisser repliait le groupe au lieu de le déplacer — c'est
  // très probablement ce qui explique des groupes qui semblaient "cassés"
  // (repliés = juste une fine barre d'en-tête, sans le corps visible).
  caret.elt.addEventListener('click', () => { group.collapsed = !group.collapsed; rebuildLibList(); saveLibrary(); });

  var nameIn = createInput(group.name).class('lib-name lib-group-name').parent(head);
  nameIn.elt.setAttribute('draggable', 'false');
  nameIn.elt.addEventListener('dblclick', () => nameIn.elt.select());
  nameIn.input(() => { group.name = nameIn.value(); saveLibrary(); });

  createButton('🗑').class('lib-del').parent(head).elt.addEventListener('click', () => deleteGroup(group.gid));

  var body = createDiv('').class('lib-group-body').parent(g);
  makeDropTarget(body, () => dropIntoGroup(group.gid));
  group.presets.forEach(p => renderPresetRow(p, body));
  if (!group.presets.length) createDiv('Drop presets here').class('lib-group-empty').parent(body);
}

// --- Sélection / suppression ---
function selectPreset(uid) {
  var p = presetById[uid];
  if (!p) return;
  selectedUid = uid;
  applyState(p.state);
  libTrigger.html(p.name || 'Preset');
  rebuildLibList();
}
// Au chargement, on démarre sur un preset choisi au hasard dans la bibliothèque
// (root ou dans un groupe, presetById les contient tous) plutôt que sur un
// réglage neutre figé — DEFAULT_PRESET_STATE ne sert plus qu'en dernier
// recours, quand la bibliothèque est vide (tout premier lancement).
function selectRandomPresetOrDefault() {
  const uids = Object.keys(presetById);
  if (uids.length) selectPreset(uids[Math.floor(Math.random() * uids.length)]);
  else applyState(DEFAULT_PRESET_STATE);
}
function deletePreset(uid) {
  var f = locate('preset', uid);
  if (f) f.arr.splice(f.idx, 1);
  delete presetById[uid];
  if (selectedUid === uid) { selectedUid = null; libTrigger.html('— No preset selected —'); }
  rebuildLibList();
  saveLibrary();
}
function deleteGroup(gid) {
  var f = locate('group', gid);
  if (!f) return;
  libItems.splice(f.idx, 1, ...f.node.presets);  // dégroupe : presets remontés à la racine
  delete groupById[gid];
  rebuildLibList();
  saveLibrary();
}

// --- Glisser-déposer (drag-and-drop natif) ---
function makeDraggable(el, kind, id) {
  el.elt.setAttribute('draggable', 'true');
  el.elt.addEventListener('dragstart', ev => {
    dragKind = kind; dragId = id;
    ev.dataTransfer.effectAllowed = 'move';
    try { ev.dataTransfer.setData('text/plain', kind + ':' + id); } catch (e) {}
    ev.stopPropagation();
  });
  el.elt.addEventListener('dragend', () => { dragKind = null; dragId = null; clearDropMarks(); });
}
function makeDropTarget(el, handler) {
  el.elt.addEventListener('dragover', ev => { ev.preventDefault(); ev.dataTransfer.dropEffect = 'move'; el.elt.classList.add('drop-hi'); });
  el.elt.addEventListener('dragleave', () => el.elt.classList.remove('drop-hi'));
  el.elt.addEventListener('drop', ev => {
    ev.preventDefault(); ev.stopPropagation();
    el.elt.classList.remove('drop-hi');
    lastDropY = ev.clientY;
    if (dragKind) handler(ev);
  });
}
function clearDropMarks() {
  document.querySelectorAll('.drop-hi').forEach(e => e.classList.remove('drop-hi'));
}
// Retire le node glissé de l'arbre et le renvoie
function pullDragged() {
  var f = locate(dragKind, dragId);
  if (!f) return null;
  f.arr.splice(f.idx, 1);
  return f.node;
}
// Dépôt sur une ligne de preset : insère avant/après (selon Y) dans le même conteneur
function dropOnPreset(targetUid, rowEl) {
  if (dragKind === 'preset' && dragId === targetUid) return;
  const dragged = pullDragged();
  if (!dragged) return;
  var t = locate('preset', targetUid);
  if (!t) { libItems.push(dragged); return finalizeDrop(); }
  if (dragged.kind === 'group' && t.arr !== libItems) { libItems.push(dragged); return finalizeDrop(); }
  const rect = rowEl.getBoundingClientRect();
  const after = (lastDropY - rect.top) > rect.height / 2 ? 1 : 0;
  t.arr.splice(t.idx + after, 0, dragged);
  finalizeDrop();
}
// Dépôt sur l'entête d'un groupe. Pour un PRESET : rejoint ce groupe (c'est la
// cible naturelle — l'en-tête, avec le nom du groupe, est bien plus visible et
// facile à viser que la petite zone "Drop presets here" du corps ; avant ce
// correctif, déposer ici se contentait de réordonner le preset à côté du
// groupe au niveau racine, sans jamais l'y intégrer). Pour un GROUPE : réordonne
// à la racine, avant/après ce groupe (pas d'imbrication de groupes).
function dropOnGroupHead(gid, headEl) {
  if (dragKind === 'group' && dragId === gid) return;
  var dragged = pullDragged();
  if (!dragged) return;
  if (dragged.kind === 'preset') {
    var g = groupById[gid];
    if (g) g.presets.push(dragged); else libItems.push(dragged);
    return finalizeDrop();
  }
  var t = locate('group', gid);
  let idx = t ? t.idx : libItems.length;
  var rect = headEl.getBoundingClientRect();
  if ((lastDropY - rect.top) > rect.height / 2) idx += 1;
  libItems.splice(idx, 0, dragged);
  finalizeDrop();
}
// Dépôt dans le corps d'un groupe : ajoute le preset à ce groupe (pas d'imbrication)
function dropIntoGroup(gid) {
  var dragged = pullDragged();
  if (!dragged) return;
  if (dragged.kind === 'group') { libItems.push(dragged); return finalizeDrop(); }
  var g = groupById[gid];
  if (g) g.presets.push(dragged); else libItems.push(dragged);
  finalizeDrop();
}
function finalizeDrop() {
  dragKind = null; dragId = null;
  rebuildLibList();
  saveLibrary();
}

// --- Vignette fixe (sert à la persistance / export) ---
function captureThumb(preset) {
  if (!preset) return;
  try {
    var src = cnv.elt;
    const side = Math.min(src.width, src.height);
    const sx = (src.width - side) / 2, sy = (src.height - side) / 2;
    const tc = document.createElement('canvas');
    tc.width = 96; tc.height = 96;
    tc.getContext('2d').drawImage(src, sx, sy, side, side, 0, 0, 96, 96);
    preset.thumb = tc.toDataURL('image/png');
    if (!preset.video) rebuildLibList();
    saveLibrary();
  } catch (e) { console.warn('Vignette non capturée', e); }
}

// --- Persistance & import/export (arbre, sans les vidéos) ---
function serializePreset(p) { return { kind: 'preset', name: p.name, thumb: p.thumb, state: p.state }; }
function serializeNode(n) {
  return n.kind === 'group'
    ? { kind: 'group', name: n.name, collapsed: !!n.collapsed, presets: n.presets.map(serializePreset) }
    : serializePreset(n);
}
function serializeLibrary() { return libItems.map(serializeNode); }

function mkPresetFrom(o) {
  var p = newPreset((o && o.state) || {});
  p.name = (o && o.name) || p.name;
  p.thumb = (o && o.thumb) || '';
  return p;
}
function deserialize(data) {
  libItems = [];
  Object.keys(presetById).forEach(k => delete presetById[k]);
  Object.keys(groupById).forEach(k => delete groupById[k]);
  (data || []).forEach(o => {
    if (o && o.kind === 'group') {
      var g = newGroup(o.name);
      g.collapsed = !!o.collapsed;
      (o.presets || []).forEach(po => g.presets.push(mkPresetFrom(po)));
      libItems.push(g);
    } else {
      libItems.push(mkPresetFrom(o));   // ancien format plat = preset simple
    }
  });
}
function saveLibrary() {
  try { localStorage.setItem(LIB_KEY, JSON.stringify(serializeLibrary())); }
  catch (e) { /* stockage indisponible (aperçu) ou plein */ }
}
function loadLibrary() {
