  // origine, donc même localStorage) resterait affiché indéfiniment à la
  // place de la bibliothèque qu'on vient de coller — vécu en pratique : un
  // export à 26 presets qui affichait encore les 20 d'un essai antérieur.
  if (Array.isArray(EMBEDDED_LIBRARY_SEED)) { applyFetchedLibrary(EMBEDDED_LIBRARY_SEED); return; }

