// nœuds exportés). Si des presets racine sont exportés EN PLUS de groupes,
// leur nombre + "Presets" s'ajoute après le dernier nom de groupe et avant
// la date. Sans aucun groupe : [NOMBRE_PRESETS]_Preset_[DATE].json. Tronque
// et alerte si le résultat dépasse la limite d'un système de fichiers.
function buildExportFilename(nodes) {
  const groupNames = nodes.filter(n => n.kind === 'group').map(n => n.name);
  const rootPresetCount = nodes.filter(n => n.kind === 'preset').length;
  let base;
  if (groupNames.length) {
    base = groupNames.map(sanitizeFilename).join('_');
    if (rootPresetCount) base += '_' + rootPresetCount + '_Presets';
  } else {
    base = rootPresetCount + '_Preset';
  }
  const suffix = '_' + todayDateString() + '.json';
  let filename = base + suffix;
  if (filename.length > MAX_FILENAME_CHARS) {
    base = base.slice(0, Math.max(1, MAX_FILENAME_CHARS - suffix.length));
    filename = base + suffix;
    showToast('Le nom du fichier exporté a été raccourci car il dépassait la limite de '
      + MAX_FILENAME_CHARS + ' caractères (trop de groupes sélectionnés).');
  }
  return filename;
}

function exportLibrary() {
  if (!libItems.length) { showToast('Library is empty.'); return; }

  var hasSelection = selectedGroupGids.size > 0 || selectedPresetUids.size > 0;
  const nodes = hasSelection
    ? libItems.filter(n => n.kind === 'group' ? selectedGroupGids.has(n.gid) : selectedPresetUids.has(n.uid))
    : libItems;
  if (hasSelection && !nodes.length) { showToast('Aucun élément sélectionné pour l’export.'); return; }

  const exportBlob = new Blob([JSON.stringify(nodes.map(serializeNode), null, 2)], { type: 'application/json' });
  var filename = buildExportFilename(nodes);

  // Le fichier au nom unique est l'export visible demandé (un par clic, jamais
  // écrasé, limité à la sélection courante s'il y en a une). library.json
  // reste toujours la bibliothèque COMPLÈTE : c'est lui que loadLibrary()
  // relit automatiquement au démarrage sur un navigateur sans cache local, et
  // un export partiel (sélection) ne doit pas l'écraser avec seulement une
  // partie des presets.
  const libraryJsonBlob = hasSelection
    ? new Blob([JSON.stringify(serializeLibrary(), null, 2)], { type: 'application/json' })
    : exportBlob;

  Promise.all([
    saveToProjectDir(exportBlob, filename),
    saveToProjectDir(libraryJsonBlob, LIB_FILENAME)
  ]).then(() => flashCheck(libExportCheckEl));
}
function handleLibFile(file) {
  let data = file && file.data;
  if (typeof data === 'string') {
    try { data = JSON.parse(data); }
    catch (e) { showToast('Could not read the library file.', 'error'); return; }
  }
  if (!Array.isArray(data)) { showToast('Invalid library file.', 'error'); return; }
  deserialize(data);
  selectedUid = null;
  libTrigger.html('— No preset selected —');
  rebuildLibList();
  scrollLibListToBottom();
  saveLibrary();
}

