// Téléchargement natif robuste (révocation différée pour ne pas annuler le DL)
function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  var a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.style.display = 'none';
  document.body.appendChild(a);
  a.click();
  setTimeout(() => { document.body.removeChild(a); URL.revokeObjectURL(url); }, 1500);
}

// Écrit directement le fichier à côté d'index.html via la route PUT de
// server.py (voir SAFE_NAME_RE côté serveur : un seul segment .json/.mp4).
// Sans ce serveur (ouverture en file://, hébergement statique...) la requête
// échoue et on retombe sur le téléchargement classique du navigateur.
// Retourne une promesse résolue en `true` si le fichier est réellement sur
// disque (écriture serveur), `false` si on est retombé sur le téléchargement
// navigateur — utile à l'appelant pour savoir si des actions qui supposent un
// vrai fichier sur disque (Play dans VLC, bouton corbeille) ont un sens.
function saveToProjectDir(blob, filename) {
  return fetch(encodeURIComponent(filename), {
    method: 'PUT',
    headers: { 'Content-Type': blob.type || 'application/octet-stream' },
    body: blob
  })
    .then(res => {
      if (!res.ok) throw new Error('HTTP ' + res.status);
      console.log('[export] enregistré dans ' + filename + ' (même dossier qu\'index.html)');
      return true;
    })
    .catch(e => {
      console.warn('[export] écriture directe indisponible, téléchargement à la place', e);
      downloadBlob(blob, filename);
      return false;
    });
}

// Nom de fichier sûr sur tous les OS (Windows interdit \ / : * ? " < > |).
function sanitizeFilename(name) {
  return (name || '').replace(/[\\/:*?"<>|]/g, '').trim() || 'animation';
}

