//  ENREGISTREMENT PRINCIPAL — WebCodecs + muxeur MP4 maison (sans dépendance)
// ============================================================================
// Diagnostic mesuré sur Firefox : captureStream()+MediaRecorder n'y annonce
// aucun encodeur VP9/AV1/H.264 (seul le VP8 générique 'video/webm' répond oui à
// isTypeSupported), et ce VP8 ignore quasiment le bitrate demandé. On contourne
// donc MediaRecorder pour l'export principal : chaque frame du canvas est
// encodée en H.264 via VideoEncoder (WebCodecs — matériel/GPU quand disponible,
// voir hardwareAcceleration plus bas), et les paquets encodés sont assemblés à
// la main en un fichier .mp4 minimal (une piste vidéo, pas d'audio) pour rester
// sans dépendance externe tout en étant lisible partout (Windows, navigateurs,
// téléphones, logiciels de montage).

// ---------- Muxeur MP4/ISO-BMFF minimal ----------
function mp4Concat(parts) {
  const total = parts.reduce((n, p) => n + p.length, 0);
