// Bitrate cible. Ce générateur peut produire des traits très fins (stroke ~0.5px)
// dont l'aliasing change de façon quasi aléatoire d'une frame à l'autre : c'est un
// pire cas pour la compression vidéo standard, la prédiction inter-images échoue
// en permanence (contenu proche du bruit pour le codec), d'où des blocs "sales" et
// des sautes visibles malgré un débit déjà généreux pour du contenu normal. On vise
// donc bien plus haut (2 bits/pixel/frame plutôt que 0,5) pour compenser.
function targetVideoBitrate(w, h) {
  const bps = w * h * FRAMERATE * 2;
  return Math.round(Math.min(200_000_000, Math.max(8_000_000, bps)));
