    if (isFirefoxMobile()) { startRecordingWebmFallback(); return; }
    showToast("L'export vidéo nécessite l'API WebCodecs (VideoEncoder), disponible sur Chrome, "
      + "Edge et les navigateurs Chromium récents — indisponible dans ce navigateur.", 'error');
