  // taille du canvas dépend de la fenêtre et peut être impaire (ex. 1232×361),
  // ce que l'encodeur refuse avec "Operation is not supported". On arrondit au
  // pixel pair inférieur et on rogne la frame en conséquence (1 px max, invisible).
  const width = cnv.elt.width - (cnv.elt.width % 2);
  const height = cnv.elt.height - (cnv.elt.height % 2);
