  // (NVENC/QuickSync/VCE...) sur le matériel grand public, là où l'accélération
  // matérielle VP9 est bien plus rare. Contrepartie : le conteneur ne peut plus
  // être du WebM strict (VP8/VP9/AV1 uniquement) — d'où le passage au MP4.
  const codec = 'avc1.640034';

