  // presque chaque frame est "difficile" (traits fins/aliasing), le VBR a tendance
  // à sous-doser par endroits en pariant sur des passages faciles qui n'arrivent
  // jamais ici — le CBR garantit le même débit soutenu sur toute la vidéo.
  const baseConfig = { codec, width, height, bitrate, framerate: FRAMERATE, latencyMode: 'quality', avc: { format: 'avc' }, bitrateMode: 'constant' };

  // Utilise l'encodeur matériel (GPU) du navigateur s'il existe pour cette config
  // exacte — nettement plus rapide que le logiciel sur une scène lourde. On teste
  // la configuration complète (pas juste le codec) : un GPU peut accepter le
  // codec seul mais refuser la combinaison avec avc:{format:'avc'} par exemple,
  // et configure() échouerait alors de façon asynchrone (silencieuse) sans ce test.
  let hardwareAcceleration = 'no-preference';
  try {
    const probe = await VideoEncoder.isConfigSupported({ ...baseConfig, hardwareAcceleration: 'prefer-hardware' });
    if (probe.supported) hardwareAcceleration = 'prefer-hardware';
  } catch (e) { /* pas grave, on reste sur no-preference */ }
