  const samples = [];
  let stopped = false;
  let encoderFailed = false;
  let frameIndex = 0;
  const frameDurationUs = Math.round(1_000_000 / FRAMERATE);
  const ENCODE_QUEUE_LIMIT = 8;
  // Repli pour buildMp4() si l'image clé n'intègre pas ses propres SPS/PPS
  // (voir le commentaire de buildMp4) : déjà au format attendu, "avcC" étant
  // exactement le payload de cette box (avc:{format:'avc'} configuré ci-dessus).
  let firstKeyframeAvcCDescription = null;

  // Garantit systématiquement la reprise de la boucle p5 (loop()) et la remise à
  // zéro de l'UI d'enregistrement, quel que soit le chemin de sortie (succès,
  // erreur de l'encodeur, exception inattendue dans pumpFrames/stop). Avant ce
  // correctif, une erreur après noLoop() pouvait geler draw() indéfiniment — le
  // canvas ne se redessinait plus du tout, donnant l'impression que plus rien
  // (dont les layouts) ne fonctionnait, jusqu'au rechargement de la page.
  function endExport() {
    if (recording || mainRecorder) {
      loop();
      recording = false;
      mainRecorder = null;
      startButton.removeAttribute('disabled');
      startButton.removeClass('active');
    }
  }

  const encoder = new VideoEncoder({
    output: (chunk, metadata) => {
      var data = new Uint8Array(chunk.byteLength);
      chunk.copyTo(data); // déjà au format attendu par le MP4 : NAL units préfixées par leur longueur (4 octets)
      const keyframe = chunk.type === 'key';
      if (keyframe && !firstKeyframeAvcCDescription && metadata?.decoderConfig?.description) {
        firstKeyframeAvcCDescription = new Uint8Array(metadata.decoderConfig.description);
      }
      samples.push({ data, keyframe, ptsUs: chunk.timestamp });
    },
    error: (e) => {
      // configure() échoue de façon asynchrone (pas d'exception synchrone) : sans
      // ce callback, pumpFrames() continuerait d'appeler encode() sur un encodeur
      // non configuré et lèverait la même erreur en boucle sans jamais débloquer
      // le bouton Start. On répare l'état immédiatement plutôt que d'attendre un
      // clic sur Stop (qui tenterait en plus de flush()/close() un encodeur déjà
      // en échec).
      console.error('[export] erreur encodeur', e);
      encoderFailed = true;
      stopped = true;
      endExport();
      showToast("L'export a échoué (encodeur vidéo indisponible pour cette configuration). Voir la console pour le détail.", 'error');
    }
  });
  try {
    encoder.configure({ ...baseConfig, hardwareAcceleration });
  } catch (e) {
    console.error('[export] configure() a échoué', e);
    showToast("L'export a échoué (configuration vidéo refusée par le navigateur). Voir la console pour le détail.", 'error');
    return;
  }

  noLoop(); // on pilote draw() nous-mêmes via redraw(), à notre rythme

  async function pumpFrames() {
    try {
      while (!stopped && !encoderFailed) {
        while (encoder.encodeQueueSize > ENCODE_QUEUE_LIMIT) {
          await new Promise(r => setTimeout(r, 0));
          if (stopped || encoderFailed) return;
        }
        redraw(); // avance l'animation d'exactement une frame virtuelle
        const frame = new VideoFrame(cnv.elt, { timestamp: frameIndex * frameDurationUs, visibleRect: { x: 0, y: 0, width, height } });
        try {
          encoder.encode(frame, { keyFrame: frameIndex % KEYFRAME_INTERVAL_FRAMES === 0 });
        } finally {
          frame.close();
        }
        frameIndex++;
        await new Promise(r => setTimeout(r, 0)); // laisse l'UI respirer (clic sur Stop, etc.)
      }
    } catch (e) {
      // Filet de sécurité : sans ce catch, une exception ici (VideoFrame invalide,
      // contexte WebGL perdu...) rejette pumpDone, et le `await pumpDone` de stop()
      // relance l'exception AVANT d'atteindre loop() — noLoop() resterait actif
      // indéfiniment.
      console.error('[export] erreur pendant la capture des frames', e);
      encoderFailed = true;
      if (!stopped) {
        stopped = true;
        endExport();
        showToast("L'export a échoué pendant la capture des frames. Voir la console pour le détail.", 'error');
      }
    }
  }
  const pumpDone = pumpFrames();

  mainRecorder = {
    state: 'recording',
    stop: async () => {
      if (stopped) return;
      stopped = true;
      mainRecorder.state = 'stopping';
      try {
        await pumpDone; // s'assurer qu'aucune frame n'est plus soumise avant de vider l'encodeur
      } catch (e) {
        // pumpFrames() a déjà géré son propre nettoyage (endExport + alert) dans
        // son catch ; on avale ici uniquement pour ne pas casser ce bloc.
      }
      if (encoderFailed) { endExport(); return; } // déjà nettoyé (par le catch ci-dessus ou le callback error())
      try {
        // Filet de sécurité, gardé par prudence (ne devrait plus se déclencher
        // puisqu'on n'accumule plus de retard avant l'arrêt).
        const FLUSH_TIMEOUT_MS = 8000;
        const timedOut = await Promise.race([
          encoder.flush().then(() => false),
          new Promise(res => setTimeout(() => res(true), FLUSH_TIMEOUT_MS))
        ]);
        if (timedOut) console.warn('[export] flush() trop long — export des frames déjà encodées.');
        encoder.close();
        if (!samples.some(s => s.keyframe)) {
          console.error('[export] aucune image clé exploitable, export annulé.');
        } else {
          var blob = buildMp4({ width, height }, samples, firstKeyframeAvcCDescription);
          // Nom = [groupe_]preset_durée.mp4 (durée réelle encodée : frameIndex,
          // pas recordFrames qui compte aussi les frames pendant une pause UI).
          // "animation" si aucun preset n'est sélectionné ; pas de segment
          // groupe si le preset est à la racine (pas dans un groupe).
          const preset = selectedUid ? presetById[selectedUid] : null;
          const group = preset ? findGroupOfPreset(preset.uid) : null;
          const durationLabel = (frameIndex / FRAMERATE).toFixed(1) + 's';
          const nameParts = [];
          if (group) nameParts.push(sanitizeFilename(group.name));
          nameParts.push(sanitizeFilename(preset ? preset.name : 'animation'));
          nameParts.push(durationLabel);
          var filename = nameParts.join('_') + '.mp4';
          saveToProjectDir(blob, filename).then(savedOnDisk => {
            flashCheck(exportCheckEl);
            // Play (VLC) et la corbeille agissent sur un vrai fichier disque :
            // pas de sens de les proposer si on est retombé sur un téléchargement.
            if (savedOnDisk) registerRecentExport(filename);
          });
        }
      } catch (e) {
        console.error('[export] finalisation du MP4 a échoué', e);
        showToast("L'export a échoué lors de la finalisation du fichier vidéo. Voir la console pour le détail.", 'error');
      } finally {
        endExport();
      }
    }
  };
  recording = true;
  recordFrames = 0;
  startButton.attribute('disabled', '');
  startButton.addClass('active');
}
function stopMainRecording() {
  if (recording && mainRecorder && mainRecorder.state === 'recording') mainRecorder.stop();
}

// Repli Firefox mobile (voir isFirefoxMobile) : capture le canvas EN DIRECT
// pendant que la boucle p5 tourne normalement (pas de noLoop()/redraw() piloté
// à la main comme pour l'export WebCodecs — MediaRecorder a besoin d'un flux
// temps réel). recordFrames/timeDisplay sont déjà mis à jour de façon
// générique dans draw() via le simple booléen "recording", donc rien à
// dupliquer ici pour l'affichage de la durée.
function startRecordingWebmFallback() {
  var mimeType = 'video/webm';
  var rec;
  try {
    rec = new MediaRecorder(cnv.elt.captureStream(FRAMERATE), {
      mimeType, videoBitsPerSecond: targetVideoBitrate(cnv.elt.width, cnv.elt.height)
    });
  } catch (e) {
    console.error('[export] MediaRecorder (repli Firefox mobile) indisponible', e);
    showToast("L'export vidéo a échoué : ni WebCodecs ni MediaRecorder ne sont utilisables dans ce navigateur.", 'error');
    return;
  }
  var chunks = [];
  rec.ondataavailable = (e) => { if (e.data.size > 0) chunks.push(e.data); };
  rec.onstop = () => {
    var blob = new Blob(chunks, { type: mimeType });
    var preset = selectedUid ? presetById[selectedUid] : null;
    var group = preset ? findGroupOfPreset(preset.uid) : null;
    var durationLabel = (recordFrames / FRAMERATE).toFixed(1) + 's';
    var nameParts = [];
    if (group) nameParts.push(sanitizeFilename(group.name));
    nameParts.push(sanitizeFilename(preset ? preset.name : 'animation'));
    nameParts.push(durationLabel);
    var filename = nameParts.join('_') + '.webm';
    saveToProjectDir(blob, filename).then((savedOnDisk) => {
      flashCheck(exportCheckEl);
      if (savedOnDisk) registerRecentExport(filename);
    });
    recording = false;
    mainRecorder = null;
    startButton.removeAttribute('disabled');
    startButton.removeClass('active');
  };
  mainRecorder = { state: 'recording', stop: async () => { if (rec.state === 'recording') rec.stop(); } };
  rec.start();
  recording = true;
  recordFrames = 0;
  startButton.attribute('disabled', '');
  startButton.addClass('active');
}
// ============================================================================
//  PROJECTEURS / FAISCEAUX LUMINEUX
// ============================================================================
// Crée les poignées DOM (corps du projecteur L1/L2 + bout de faisceau)
function buildBeamHandles() {
  beams.forEach((b, i) => {
    var body = document.createElement('div');
    body.className = 'beam-body l' + (i + 1);
    body.textContent = 'L' + (i + 1);
    document.body.appendChild(body);
    beamBodyEls[i] = body;

    const tip = document.createElement('div');
    tip.className = 'beam-tip';
    tip.title = 'Rotate';
    document.body.appendChild(tip);
    beamTipEls[i] = tip;

    const cone = document.createElement('div');
    cone.className = 'beam-cone';
    cone.title = 'Range & cone angle';
    document.body.appendChild(cone);
    beamConeEls[i] = cone;

    const soft = document.createElement('div');
    soft.className = 'beam-soft';
    soft.title = 'Edge softness (blur with distance)';
    document.body.appendChild(soft);
    beamSoftEls[i] = soft;

    const mask = document.createElement('div');
    mask.className = 'beam-mask';
    mask.title = 'Hide / show projector';
    document.body.appendChild(mask);
    beamMaskEls[i] = mask;

    body.addEventListener('pointerdown', ev => { dragBeam = { i, part: 'body' }; ev.preventDefault(); });
    tip.addEventListener('pointerdown', ev => { dragBeam = { i, part: 'tip' }; ev.preventDefault(); });
    cone.addEventListener('pointerdown', ev => { dragBeam = { i, part: 'cone' }; ev.preventDefault(); });
    soft.addEventListener('pointerdown', ev => { dragBeam = { i, part: 'soft' }; ev.preventDefault(); });
    mask.addEventListener('click', ev => { b.masked = !b.masked; ev.stopPropagation(); });
  });

  document.addEventListener('pointermove', onBeamDrag);
  document.addEventListener('pointerup', () => { dragBeam = null; });
}

// Centre du canvas en coordonnées écran (viewport)
function canvasCenter() {
  var r = cnv.elt.getBoundingClientRect();
  return { cx: r.left + r.width / 2, cy: r.top + r.height / 2 };
}

// Approximation : suppose une caméra non tournée/zoomée (projection plate
// écran → plan XY). C'est le cas courant puisque orbitControl() est coupé
// pendant tout glisser de projecteur (voir draw()), donc la caméra ne bouge
// pas PENDANT l'édition — mais si elle a été pivotée/zoomée AVANT de saisir la
// poignée, le calcul reste décalé (une vraie reprojection 3D inverse serait
// nécessaire pour rester exact dans ce cas).
function onBeamDrag(ev) {
  if (!dragBeam) return;
  const { cx, cy } = canvasCenter();
  var b = beams[dragBeam.i];
  var wx = ev.clientX - cx, wy = ev.clientY - cy;   // coords monde
  if (dragBeam.part === 'body') { b.x = wx; b.y = wy; }
  else if (dragBeam.part === 'tip') { b.angle = Math.atan2(wy - b.y, wx - b.x); }
  else if (dragBeam.part === 'cone') { // distance = portée, écart à l'axe = demi-angle du cône
    const dx = wx - b.x, dy = wy - b.y;
    b.range = Math.min(1400, Math.max(60, Math.hypot(dx, dy)));
    let da = Math.atan2(dy, dx) - b.angle;
    da = Math.atan2(Math.sin(da), Math.cos(da));
    b.cone = Math.min(1.4, Math.max(0.05, Math.abs(da)));
  }
  else { // 'soft' : distance au projecteur → intensité du flou (bord doux avec l'éloignement)
    const dist = Math.hypot(wx - b.x, wy - b.y);
    b.softness = Math.min(1, Math.max(0, (dist - 50) / 150));
  }
}

// Repositionne les poignées sur le canvas (appelé chaque frame).
// Approximation plane (caméra par défaut, non pivotée/zoomée) : p5.js n'a pas
// d'équivalent du screenX()/screenY() de Processing pour reprojeter un point
// 3D sous la caméra ACTUELLE de façon simple, et reconstruire ça à la main via
// les matrices internes (_renderer.uMVMatrix/uPMatrix) serait trop fragile
// sans validation approfondie. Résultat concret : les poignées de faisceau
// restent bien alignées à la vue par défaut, mais peuvent visuellement
// dériver des cônes réellement dessinés une fois la caméra pivotée/zoomée à
// la souris (orbitControl).
function positionBeamHandles() {
  const { cx, cy } = canvasCenter();
  beams.forEach((b, i) => {
    var body = beamBodyEls[i], tip = beamTipEls[i], cone = beamConeEls[i], soft = beamSoftEls[i], mask = beamMaskEls[i];
    if (!body) return;
    const on = sliders['l' + (i + 1)].value() > 0;
    if (!on) {
      [body, tip, cone, soft, mask].forEach(e => { e.style.display = 'none'; });
      return;
    }
    // L'œil de masquage reste toujours accessible tant que la lumière est active
    mask.style.display = 'flex';
    mask.style.left = (cx + b.x) + 'px';
    mask.style.top = (cy + b.y - 26) + 'px';
    mask.textContent = b.masked ? '🚫' : '👁';
    mask.classList.toggle('is-masked', !!b.masked);

    if (b.masked) { [body, tip, cone, soft].forEach(e => { e.style.display = 'none'; }); return; }

    body.style.display = 'flex';
    body.style.left = (cx + b.x) + 'px';
    body.style.top = (cy + b.y) + 'px';
    body.style.transform = 'translate(-50%,-50%) rotate(' + b.angle + 'rad)';

    tip.style.display = 'block';
    tip.style.left = (cx + b.x + Math.cos(b.angle) * BEAM_TIP) + 'px';
    tip.style.top = (cy + b.y + Math.sin(b.angle) * BEAM_TIP) + 'px';

    const ca = b.angle + b.cone;   // poignée portée/angle : un bord du cône
    cone.style.display = 'block';
    cone.style.left = (cx + b.x + Math.cos(ca) * b.range) + 'px';
    cone.style.top = (cy + b.y + Math.sin(ca) * b.range) + 'px';

    const sa = b.angle - b.cone;   // poignée flou : bord opposé, distance = intensité du flou
    const sd = 50 + b.softness * 150;
    soft.style.display = 'block';
    soft.style.left = (cx + b.x + Math.cos(sa) * sd) + 'px';
    soft.style.top = (cy + b.y + Math.sin(sa) * sd) + 'px';
  });
}

// Étendues angulaire/radiale réellement utilisées par un faisceau une fois le
// flou pris en compte. Avant ce correctif, la coupure nette restait TOUJOURS
// exactement à b.cone/b.range quel que soit softness (qui ne faisait que
// reformer la courbe à l'intérieur de cette limite fixe, et dans le mauvais
// sens : un exposant croissant rend la transition plus dure, pas plus douce)
// — d'où un bord visuellement identique ("une ligne nette") peu importe le
// curseur. Ici, innerCone/innerRange restent pleinement éclairés, et la vraie
// coupure (outerCone/outerRange) recule d'autant plus loin que softness est
// grand : la zone de dégradé s'élargit réellement.
function beamExtents(b) {
  var soft = b.softness || 0;
  return {
    innerCone: b.cone * 0.55,
    outerCone: b.cone * (1 + soft * 1.8),
    innerRange: b.range * 0.55,
    outerRange: b.range * (1 + soft * 1.2)
  };
}
// Fraction d'intensité [0,1] à un écart angulaire/une distance donnés, dégradé
// linéaire entre la zone pleinement éclairée et la coupure réelle.
function beamFalloff(da, dist, ext) {
  const angFall = da <= ext.innerCone ? 1
    : da >= ext.outerCone ? 0
    : 1 - (da - ext.innerCone) / (ext.outerCone - ext.innerCone);
  const distFall = dist <= ext.innerRange ? 1
    : dist >= ext.outerRange ? 0
    : 1 - (dist - ext.innerRange) / (ext.outerRange - ext.innerRange);
  return angFall * distFall;
}

// Multiplicateur de lumière (r,g,b) reçu en un point monde, ou null si tout éteint
function beamLight(wx, wy) {
  const inten = [sliders.l1.value() / 100, sliders.l2.value() / 100];
  if (inten[0] <= 0 && inten[1] <= 0) return null;
  let ar = BEAM_AMBIENT, ag = BEAM_AMBIENT, ab = BEAM_AMBIENT;
  beams.forEach((b, i) => {
    const k = inten[i];
    if (k <= 0) return;
    var dx = wx - b.x, dy = wy - b.y;
    var dist = Math.hypot(dx, dy);
    var da = Math.atan2(dy, dx) - b.angle;
    da = Math.abs(Math.atan2(Math.sin(da), Math.cos(da)));   // écart angulaire [0,π]
    const ext = beamExtents(b);
    if (da > ext.outerCone || dist > ext.outerRange) return;
    var c = k * beamFalloff(da, dist, ext);
    ar += c * b.color[0] / 255; ag += c * b.color[1] / 255; ab += c * b.color[2] / 255;
  });
  return [ar, ag, ab];
}

// Éclairage 3D réel : ambiance douce + relief léger + un spotLight par faisceau actif.
// Les faisceaux masqués éclairent quand même (le masquage ne cache que le visuel).
function setupLights3D(v) {
  ambientLight(70);
  directionalLight(80, 80, 80, 0.3, 0.4, -1);   // relief minimal même sans faisceau
  const inten = [v.l1 / 100, v.l2 / 100];
  beams.forEach((b, i) => {
    var k = inten[i];
    if (k <= 0) return;
    const px = b.x, py = b.y, pz = 260;                     // projecteur devant la scène
    const tx = b.x + Math.cos(b.angle) * b.range * 0.5;     // vise un point du plan
    const ty = b.y + Math.sin(b.angle) * b.range * 0.5;
    var dx = tx - px, dy = ty - py, dz = -pz;
    const dl = Math.hypot(dx, dy, dz) || 1;
    var ext = beamExtents(b);
    // Angle élargi par le softness (comme en 2D) + concentration plus basse :
    // le halo déborde visiblement du cône nominal quand on augmente le flou,
    // au lieu d'un angle fixe qui ne bougeait jamais.
    const conc = 40 - (b.softness || 0) * 37;   // flou grand → faible concentration → bord doux
    spotLight(b.color[0] * k, b.color[1] * k, b.color[2] * k,
              px, py, pz, dx / dl, dy / dl, dz / dl,
              Math.min(1.45, ext.outerCone), Math.max(2, conc));
  });
}

// Dessine les cônes de faisceau sur la scène (en coords monde, centre origine).
// Rendu en tuiles angle×distance dont l'alpha suit beamFalloff : le dégradé
// affiché est donc le même que celui réellement appliqué à l'éclairage, et
// s'élargit visiblement avec softness au lieu d'un triangle à bord fixe.
const BEAM_INDICATOR_ANGLE_STEPS = 10;
const BEAM_INDICATOR_DIST_STEPS = 10;
function drawBeamIndicators() {
  const inten = [sliders.l1.value() / 100, sliders.l2.value() / 100];
  if (inten[0] <= 0 && inten[1] <= 0) return;
  drawingContext.disable(drawingContext.DEPTH_TEST);
  beams.forEach((b, i) => {
    var k = inten[i];
    if (k <= 0 || b.masked) return;
    var ext = beamExtents(b);
    push();
    translate(b.x, b.y);
    rotate(b.angle);
    noStroke();
    Array.from({ length: BEAM_INDICATOR_ANGLE_STEPS }).forEach((_, ai) => {
      const a0 = -ext.outerCone + (2 * ext.outerCone) * (ai / BEAM_INDICATOR_ANGLE_STEPS);
      const a1 = -ext.outerCone + (2 * ext.outerCone) * ((ai + 1) / BEAM_INDICATOR_ANGLE_STEPS);
      const aMid = Math.abs((a0 + a1) / 2);
      Array.from({ length: BEAM_INDICATOR_DIST_STEPS }).forEach((__, di) => {
        const r0 = ext.outerRange * (di / BEAM_INDICATOR_DIST_STEPS);
        const r1 = ext.outerRange * ((di + 1) / BEAM_INDICATOR_DIST_STEPS);
        const fall = beamFalloff(aMid, (r0 + r1) / 2, ext);
        if (fall <= 0.02) return;
        fill(b.color[0], b.color[1], b.color[2], 55 * k * fall);
        beginShape();
        vertex(r0 * Math.cos(a0), r0 * Math.sin(a0));
        vertex(r1 * Math.cos(a0), r1 * Math.sin(a0));
        vertex(r1 * Math.cos(a1), r1 * Math.sin(a1));
        vertex(r0 * Math.cos(a1), r0 * Math.sin(a1));
        endShape(CLOSE);
      });
    });
    pop();
  });
}

// ============================================================================
//  STYLES (injectés — rien à modifier dans index.html)
// ============================================================================
// Sur OpenProcessing, la page HTML/le <head> (donc la balise <meta viewport>
// d'index.html) ne partent PAS avec l'export — seul ce <script> est collé
// (voir exportForOpenProcessing ci-dessus). Sans "width=device-width", un
// mobile met en page à une largeur desktop par défaut puis zoome pour que ça
// tienne à l'écran : les @media (max-width:...) ci-dessous ne se déclenchent
// alors jamais, quelle que soit la taille réelle de l'écran. On force donc la
// balise ici, dans le JS, pour ne plus dépendre du HTML fourni par l'hôte.
function ensureViewportMeta() {
  let m = document.querySelector('meta[name="viewport"]');
  if (!m) { m = document.createElement('meta'); m.name = 'viewport'; document.head.appendChild(m); }
  m.content = 'width=device-width, initial-scale=1';
}

function injectStyles() {
  ensureViewportMeta();
  const css = `
  :root{
    --bg:#12141c; --panel:#1a1d29; --elev:#232838; --line:#ffffff14;
    --text:#e7e9f2; --muted:#8b90a8; --accent:#8896ff; --rec:#ff6b6b;
    --track:#333850; --radius:10px;
    font-family:system-ui,-apple-system,"Segoe UI",sans-serif;
  }
  body{ margin:0; background:var(--bg); color:var(--text); }
  /* 100dvh (avec repli 100vh pour les vieux navigateurs) plutôt que 100vh
     partout ici : sur mobile, 100vh inclut l'espace où peut se rétracter la
     barre d'adresse, donc dépasse souvent la zone réellement visible. Avec le
     panneau empilé en bas (voir le @media plus bas), il pouvait alors se
     retrouver rendu sous le bord visible réel — invisible, et #app en
     overflow:hidden empêchait tout scroll pour l'atteindre. 100dvh suit la
     vraie hauteur visible et évite ça. */
  #app{ display:flex; align-items:stretch; height:100vh; height:100dvh; overflow:hidden; }
  #stage{ flex:1 1 auto; min-width:0; height:100vh; height:100dvh; box-sizing:border-box;
          padding:12px; display:flex; align-items:center; justify-content:center; }
  #stage canvas{ border-radius:var(--radius); box-shadow:0 8px 30px #0007; display:block; }

  #panel-toggle{
    position:fixed; top:16px; right:16px; z-index:20;
    width:40px; height:40px; padding:0; font-size:18px; line-height:1;
    background:var(--elev); color:var(--text); border:1px solid var(--line);
    border-radius:var(--radius); cursor:pointer;
  }
  #panel-toggle:hover{ background:var(--accent); border-color:transparent; }

  #panel{ width:280px; overflow:hidden; transition:width .25s ease; }
  #panel.collapsed{ width:0; }
  .panel-inner{
    width:280px; box-sizing:border-box; height:100vh; height:100dvh; overflow-y:auto;
    background:var(--panel); border-left:1px solid var(--line); padding:14px 13px 40px;
  }
  .panel-header{ display:flex; align-items:center; justify-content:space-between; margin-bottom:12px; }
  .panel-title{ font-size:15px; font-weight:600; letter-spacing:.3px; }
  .panel-close{
    width:26px; height:26px; padding:0; font-size:13px; background:transparent;
    color:var(--muted); border:1px solid var(--line); border-radius:8px; cursor:pointer;
  }
  .panel-close:hover{ color:var(--text); background:var(--elev); }

  .section{ margin-bottom:20px; }
  .section-label{
    font-size:11px; text-transform:uppercase; letter-spacing:1px; color:var(--muted);
    margin:0 0 10px; border-bottom:1px solid var(--line); padding-bottom:6px;
  }

  .row{ display:grid; grid-template-columns:80px 1fr 36px; align-items:center; gap:7px; margin:7px 0; }
  .row-label{ font-size:12px; color:var(--muted); }
  .row-value{ font-size:12px; text-align:right; color:var(--text); font-variant-numeric:tabular-nums; }
  .row-check{ display:flex; }

  /* Bloc déplaçable (glisser-déposer) autour de chaque slider d'une section ;
     le contour en pointillés au survol vient de .drop-hi (partagé avec la
     bibliothèque de presets). Seule l'étiquette (poignée) est "grab" : le
     curseur du slider lui-même doit garder son comportement natif normal. */
  .slider-slot.dragging{ opacity:.4; }
  .slider-drag-handle{ cursor:grab; }
  .slider-drag-handle:active{ cursor:grabbing; }

  /* Section repliable "Color effects" */
  .subsection{ margin-top:12px; border:1px solid var(--line); border-radius:8px; overflow:hidden; }
  .subsection-head{
    display:flex; align-items:center; justify-content:space-between; gap:8px;
    padding:9px 11px; cursor:pointer; user-select:none; background:var(--elev);
    font-size:11px; text-transform:uppercase; letter-spacing:1px; color:var(--muted);
  }
  .subsection-head:hover{ color:var(--text); }
  .subsection-caret{ transition:transform .2s ease; }
  .subsection:not(.collapsed) .subsection-caret{ transform:rotate(90deg); }
  .subsection-body{ padding:4px 11px 10px; }
  .subsection.collapsed .subsection-body{ display:none; }

  input[type=range]{
    -webkit-appearance:none; appearance:none; width:100%; height:4px;
    background:var(--track); border-radius:4px; outline:none; cursor:pointer;
  }
  input[type=range]::-webkit-slider-thumb{
    -webkit-appearance:none; appearance:none; width:10.5px; height:10.5px; border-radius:50%;
    background:var(--accent); border:2px solid #fff3; cursor:pointer; transition:background .15s;
  }
  input[type=range]::-webkit-slider-thumb:hover{ background:#fff; }
  input[type=range]::-moz-range-thumb{
    width:10.5px; height:10.5px; border-radius:50%; background:var(--accent);
    border:2px solid #fff3; cursor:pointer;
  }
  /* Slider verrouillé (ex. Red/Green/Blue pendant que Gradient > 0, voir
     refreshValueSpans()) : le curseur suit toujours une valeur en direct,
     juste plus question de le déplacer à la main tant qu'il l'affiche. */
  input[type=range]:disabled{ cursor:not-allowed; opacity:.55; }
  input[type=range]:disabled::-webkit-slider-thumb{ cursor:not-allowed; }
  input[type=range]:disabled::-moz-range-thumb{ cursor:not-allowed; }

  .p5-radio{ display:flex; gap:14px; }
  .p5-radio label{ display:flex; align-items:center; gap:4px; font-size:12px; color:var(--text); cursor:pointer; }
  .p5-radio input[type=radio]{ accent-color:var(--accent); cursor:pointer; }

  .row-radio{ margin:10px 0 4px; }
  .row-radio .row-label{ display:block; margin-bottom:6px; }
  .layout-btns{ display:grid; grid-template-columns:repeat(4, 1fr); gap:6px; }
  .layout-btn{
    position:relative; padding:6px 3px; font-size:10.5px; text-align:center;
    white-space:nowrap; overflow:hidden; text-overflow:ellipsis;
  }
  /* Coche verte (même style que les coches de confirmation d'export) en
     surimpression sur le layout actuellement sélectionné. */
  .layout-btn.active::after{
    content:'✓'; position:absolute; top:-6px; right:-4px;
    width:14px; height:14px; border-radius:50%;
    background:#2ecc71; color:#fff; font-size:9px; font-weight:700;
    display:flex; align-items:center; justify-content:center; line-height:1;
  }

  .p5-check label{ display:flex; align-items:center; gap:7px; font-size:12px; color:var(--text); cursor:pointer; }
  .p5-check input[type=checkbox]{ accent-color:var(--accent); width:15px; height:15px; cursor:pointer; }

  #panel button{
    background:var(--elev); color:var(--text); border:1px solid var(--line);
    border-radius:8px; padding:7px 11px; font-size:12px; cursor:pointer; transition:.15s;
  }
  #panel button:hover{ background:var(--accent); border-color:transparent; color:#fff; }
  #panel button:disabled{ opacity:.45; cursor:not-allowed; }

  /* Liste des presets (gauche, plus étroite) + colonne des 4 actions (droite) */
  .lib-layout{ display:flex; align-items:flex-start; gap:8px; }
  .lib{ position:relative; flex:0 0 70%; min-width:0; }
  .lib-actions{ flex:1 1 auto; min-width:0; display:flex; flex-direction:column; gap:6px; }
  .lib-actions button{ width:100%; box-sizing:border-box; padding:7px 4px; font-size:11px; }
  /* Bouton Export + sa coche de succès, côte à côte sur une même ligne */
  .lib-action-row{ display:flex; align-items:center; gap:5px; }
  .lib-action-row button{ flex:1 1 auto; width:auto; }
  .btn-select-export.active{ background:var(--accent); border-color:transparent; color:#fff; }
  .lib-export-check{ flex:0 0 auto; accent-color:var(--accent); width:15px; height:15px; cursor:pointer; margin:0; }

  .lib-trigger{
    width:100%; box-sizing:border-box; display:flex; align-items:center; justify-content:space-between;
    background:var(--elev); color:var(--text); border:1px solid var(--line);
    border-radius:8px; padding:8px 9px; font-size:12px;
  }
  /* overflow-anchor:none : sans ça, l'ancrage de scroll automatique du
     navigateur reprend la main juste après notre restauration explicite de
     scrollTop dans rebuildLibList() (vidage + reconstruction complète du
     contenu à chaque clic sur un preset). */
  .lib-list{ margin-top:6px; max-height:320px; overflow-y:auto; overflow-anchor:none; display:flex; flex-direction:column; gap:6px; }
  .lib-item{ flex-shrink:0; display:flex; align-items:center; gap:6px; background:var(--elev); border:1px solid var(--line); border-radius:8px; padding:5px; }
  .lib-thumb{ width:34px; height:34px; flex:0 0 auto; border-radius:6px; background:#000 center/cover no-repeat; object-fit:cover; cursor:pointer; display:block; }
  .lib-name{
    flex:1 1 auto; min-width:0; width:100%; box-sizing:border-box; background:transparent;
    border:1px solid transparent; color:var(--text); font-size:12px; border-radius:5px; padding:4px 5px;
  }
  .lib-name:hover{ border-color:var(--line); }
  .lib-name:focus{ outline:none; border-color:var(--accent); background:var(--panel); }
  .lib-del{ flex:0 0 auto; padding:5px 7px !important; }
  .lib-item.selected{ border-color:var(--accent); }
  .lib-grip{ flex:0 0 auto; color:var(--muted); cursor:grab; font-size:12px; line-height:1; user-select:none; padding:0 1px; }
  .lib-item, .lib-group-head{ cursor:default; }

  /* Groupes */
  /* flex-shrink:0 est le vrai correctif du "groupe invisible" : dans un conteneur
     flex (.lib-list) plus haut que sa max-height, le moteur flexbox doit
     compresser des enfants pour tenir dans l'espace — et un enfant avec
     overflow:hidden (ici, pour arrondir les coins) perd sa taille minimale de
     contenu, ce qui l'autorise à être écrasé jusqu'à 0px alors que les autres
     lignes (.lib-item, sans overflow:hidden) résistent. Avec beaucoup de
     presets, tout l'écrasement retombait sur le groupe — d'où un groupe qui
     semblait disparaître dès qu'il y avait "trop" de presets au-dessus.
     flex-shrink:0 retire .lib-group du calcul de compression : le conteneur
     défile au lieu d'écraser ses enfants. */
  .lib-group{ flex-shrink:0; border:1px solid var(--line); border-radius:8px; overflow:hidden; }
  .lib-group-head{ display:flex; align-items:center; gap:6px; padding:6px 7px; background:#2b3048; }
  /* Zone cliquable large et repérable (icône + fond au survol) : un groupe
     replié par erreur en saisissant l'en-tête trop près du caret était la
     cause la plus probable des groupes "invisibles" (juste une fine barre). */
  .lib-group-caret{
    flex:0 0 auto; display:flex; align-items:center; justify-content:center;
    width:20px; height:20px; border-radius:5px; color:var(--muted); cursor:pointer;
  }
  .lib-group-caret:hover{ background:#ffffff1a; color:var(--text); }
  .lib-group-name{ font-weight:600; }
  /* Repère visuel de hiérarchie (type panneau de calques) : filet vertical +
     retrait, pour que les presets d'un groupe se voient clairement comme ses
     enfants plutôt que comme une simple liste indentée. */
  .lib-group-body{
    display:flex; flex-direction:column; gap:6px; padding:8px 6px 8px 8px;
    margin-left:10px; border-left:2px solid #8896ff66;
  }
  /* Pas de marge propre ici : le corps du groupe indente déjà (filet + marge
     ci-dessus) — un second décalage rognait trop la largeur déjà limitée du
     champ de nom dans ce panneau étroit. */
  .lib-group-body .lib-item .lib-thumb{ width:28px; height:28px; }
  .lib-group.collapsed .lib-group-body{ display:none; }
  .lib-group-empty{ font-size:10px; color:var(--muted); text-align:center; padding:14px 6px; min-height:24px; display:flex; align-items:center; justify-content:center; border:1px dashed var(--line); border-radius:6px; }

  /* Glisser-déposer */
  .drop-hi{ outline:2px dashed var(--accent); outline-offset:-2px; }
  .lib-root-drop{ flex-shrink:0; font-size:10px; color:var(--muted); text-align:center; padding:5px; border:1px dashed transparent; border-radius:6px; }
  .lib-root-drop.drop-hi{ border-color:var(--accent); outline:none; }

  .record-btns{ display:flex; flex-wrap:wrap; align-items:center; gap:8px; }
  .record-btns button{ flex:1; min-width:80px; }
  .btn-rec.active{ background:var(--rec) !important; border-color:transparent; color:#fff; }
  #panel .btn-rec:hover{ background:var(--rec); }
  .record-time{ font-size:11px; color:var(--muted); margin-top:8px; }

  /* Gros bouton d'export OpenProcessing, en bas du panneau */
  .section.export-op{ margin-top:4px; }
  .btn-export-op{
    width:100%; box-sizing:border-box; padding:14px; font-size:13px; font-weight:700;
    background:var(--accent); color:#fff; border:none;
  }
  .btn-export-op:hover{ background:#a3affb; }
  .btn-export-op-frozen{ margin-top:12px; background:var(--elev); color:var(--text); border:1px solid var(--line); }
  .btn-export-op-frozen:hover{ background:var(--accent); border-color:transparent; color:#fff; }
  .export-op-hint{ font-size:10px; color:var(--muted); margin-top:8px; line-height:1.4; }

  /* Coche de confirmation d'export, à droite de "Stop & save" */
  .export-check{
    flex:0 0 auto; display:none; align-items:center; justify-content:center;
    width:22px; height:22px; border-radius:50%;
    background:#2ecc7133; color:#2ecc71; font-size:13px; font-weight:700;
    opacity:0; transition:opacity .2s ease;
  }
  .export-check.show{ display:flex; opacity:1; }

  /* Message flottant non bloquant (remplace alert()) */
  #toast{
    position:fixed; left:50%; bottom:24px; z-index:50;
    max-width:420px; padding:10px 16px; border-radius:var(--radius);
    background:var(--elev); color:var(--text); border:1px solid var(--line);
    font-size:13px; line-height:1.4; text-align:center; box-shadow:0 8px 30px #0007;
    opacity:0; pointer-events:none;
    transform:translateX(-50%) translateY(20px);
    transition:opacity .2s ease, transform .2s ease;
  }
  #toast.show{ opacity:1; transform:translateX(-50%) translateY(0); }
  #toast.toast-error{ border-color:#e5484d; }

  /* Historique des 5 derniers exports vidéo : bouton Play (VLC) + corbeille */
  .recent-exports{ display:flex; flex-direction:column; gap:6px; margin-top:10px; }
  .export-row{ display:flex; align-items:center; gap:6px; }
  .btn-play-export{
    flex:1 1 auto; min-width:0; box-sizing:border-box; text-align:left; font-size:11px;
    overflow:hidden; text-overflow:ellipsis; white-space:nowrap;
  }
  .export-row .lib-del{ flex:0 0 auto; }

  /* Projecteurs déplaçables (poignées sur le canvas) */
  .beam-body{
    position:fixed; z-index:40; width:36px; height:22px; box-sizing:border-box;
    display:flex; align-items:center; justify-content:center;
    background:#2b3150; border:1px solid #ffffff44; border-radius:5px;
    color:#fff; font-size:10px; font-weight:700; letter-spacing:.5px;
    cursor:grab; touch-action:none; box-shadow:0 2px 8px #0009; user-select:none;
  }
  .beam-body::after{
    content:''; position:absolute; right:-7px; top:50%; transform:translateY(-50%);
    width:11px; height:11px; border-radius:50%;
  }
  .beam-body.l1::after{ background:radial-gradient(circle,#fff,#ffcb96); box-shadow:0 0 10px #ffb066cc; }
  .beam-body.l2::after{ background:radial-gradient(circle,#fff,#9ec6ff); box-shadow:0 0 10px #6aa4ffcc; }
  .beam-tip{
    position:fixed; z-index:40; width:14px; height:14px; box-sizing:border-box;
    border-radius:50%; background:#ffffff22; border:1.5px solid var(--accent);
    transform:translate(-50%,-50%); cursor:grab; touch-action:none;
  }
  .beam-cone{
    position:fixed; z-index:40; width:13px; height:13px; box-sizing:border-box;
    border-radius:3px; background:#ffffff18; border:1.5px solid #ffd27a;
    transform:translate(-50%,-50%) rotate(45deg); cursor:grab; touch-action:none;
  }
  .beam-soft{
    position:fixed; z-index:40; width:14px; height:14px; box-sizing:border-box;
    border-radius:50%; background:radial-gradient(circle,#ffffff33,#ffffff00 70%);
    border:1.5px dashed #b9a7ff; transform:translate(-50%,-50%); cursor:grab; touch-action:none;
  }
  .beam-mask{
    position:fixed; z-index:41; width:20px; height:20px; box-sizing:border-box;
    display:flex; align-items:center; justify-content:center;
    border-radius:50%; background:#1a1d29cc; border:1px solid #ffffff33;
    font-size:11px; cursor:pointer; transform:translate(-50%,-50%); user-select:none;
  }
  .beam-mask.is-masked{ opacity:.7; border-color:var(--rec); }

  /* ---- Mobile / écran étroit (téléphone en vertical) ----
     Un panneau à côté du canvas (même réduit à 50vw) reste étroit dès qu'on
     tient compte de sa hauteur d'écran limitée : on empile donc plutôt canvas
     et panneau verticalement — canvas en haut sur toute la largeur (2/3 de la
     hauteur), panneau en bas sur toute la largeur (1/3 restant, avec son
     propre défilement interne). Le panneau garde alors sa largeur normale, ce
     qui permet de revenir aux rangées horizontales (étiquette + curseur +
     valeur) et aux grilles de boutons du desktop — inutile de les empiler,
     il y a maintenant assez de place en largeur.
     #panel passe en flex:none avec une hauteur fixe en vh (au lieu du
     width:0 du mode desktop) pour l'ouverture/fermeture ; le 33.34vh est
     dupliqué en constante (0.3334) dans stageSize() (JS), qui calcule la
     taille du canvas sans lire le DOM (voir le commentaire de stageSize()).
     "and (pointer:coarse)" : cible un écran tactile (téléphone/tablette), pas
     juste une fenêtre étroite — une fenêtre desktop (souris = pointer fin)
     redimensionnée sous 700px, par ex. le volet d'aperçu de l'éditeur de code
     OpenProcessing, garde alors le layout desktop normal au lieu de basculer
     par erreur en mode mobile. */
  @media (max-width: 700px) and (pointer: coarse){
    #app{ flex-direction:column; }
    #stage{ flex:1 1 0; height:auto; width:100%; padding:8px; }
    #panel{ flex:0 0 auto; width:100%; height:calc(33.34vh + 100px); transition:height .25s ease; }
    #panel.collapsed{ width:100%; height:0; }
    .panel-inner{ width:100%; height:100%; border-left:none; border-top:1px solid var(--line); }
    #panel-toggle{ top:10px; right:10px; width:36px; height:36px; font-size:16px; }

    /* Cible tactile agrandie (10.5px → 16px) pour rester facile à saisir du
       doigt, même si les rangées restent en disposition horizontale. */
    input[type=range]{ height:6px; }
    input[type=range]::-webkit-slider-thumb{ width:16px; height:16px; }
    input[type=range]::-moz-range-thumb{ width:16px; height:16px; }
  }
  `;
  const style = document.createElement('style');
  style.textContent = css;
  document.head.appendChild(style);
}

custom_css:
/* === 4K MV Pure Canvas - 全域控制項與 UI 面板隱藏 === */
.dg, .lil-gui, .qs_main, .opc-control, #opc-control-panel, .control-panel, .gui-container,
[class*='gui'], [id*='gui'], [class*='control'], [id*='control'],
[class*='instruction'], [id*='instruction'], [class*='info'], [id*='info'],
[class*='fps'], [id*='fps'], [class*='overlay'], [id*='overlay'],
input, button, select, textarea, label, form {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
  pointer-events: none !important;
}
